/* ===== SOURCE: app.js ===== */
const STORAGE_KEY='everfall_lspd_cases_satmap_v1',LIBRARY_KEY='everfall_custom_icons_v1',DB_KEY='everfall_db_records_v1';
const $=id=>document.getElementById(id);const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seedCases=[{id:'EF-26-014',caseNo:'EF-26-014',status:'Open',location:'Legion Square',detective:'Unassigned',suspect:'Unknown',notes:'Sample investigation. Add a map position to display its pin.',lat:null,lng:null,updated:new Date().toISOString()},{id:'EF-26-011',caseNo:'EF-26-011',status:'Active',location:'Pillbox Hill',detective:'Detective Bureau',suspect:'Person of interest',notes:'Sample case record for demonstration.',lat:null,lng:null,updated:new Date().toISOString()}];
function read(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return v??fallback}catch{return fallback}}
let cases=read(STORAGE_KEY,seedCases),iconLibrary=read(LIBRARY_KEY,[]),database=read(DB_KEY,{}),selectedId=null,editingId=null,pendingLocation=null,placingForId=null,placementMode=false,detailTab='overview',currentSection='map',tempImage='',pinKind='investigation';
const colors={Open:'#f05468',Active:'#f4b73f',Closed:'#58d68b',Cold:'#83b7ff'};
function saveCases(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(cases));window.EF8E?.onLocalSave?.(cases);return true}catch{toast('Browser storage full. Try a smaller image.');return false}}
function saveLibrary(){try{localStorage.setItem(LIBRARY_KEY,JSON.stringify(iconLibrary));return true}catch{toast('Image library storage is full.');return false}}
function saveDb(){localStorage.setItem(DB_KEY,JSON.stringify(database));window.EF8H2?.localChanged("gangs");window.EF8H5?.localChanged?.()}
function fmtDate(v){return v?new Date(v).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—'}
function toast(message){$('toast').textContent=message;$('toast').classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').classList.add('hidden'),3100)}
const MAP_WIDTH=2048,MAP_HEIGHT=3072;
const map=L.map('map',{crs:L.CRS.Simple,minZoom:-2,maxZoom:4,zoomSnap:.25,zoomControl:true,attributionControl:false,zoomAnimation:false,fadeAnimation:false,markerZoomAnimation:false});const bounds=[[-MAP_HEIGHT,0],[0,MAP_WIDTH]];L.imageOverlay('assets/oulsen-nogrid.webp',bounds).addTo(map);map.fitBounds(bounds);
function worldToMap(x,y){return[-(1886.5-0.200*y),840.5+0.196*x]}
let postals=Array.isArray(window.EVERFALL_POSTALS)?window.EVERFALL_POSTALS:[];
// Image-to-world alignment checked against the original satellite image and user screenshot.
const POSTAL_CALIBRATION_KEY='eflspddb_postal_image_calibration_v2';
let postalCalibrations=read(POSTAL_CALIBRATION_KEY,{}),calibratingPostal=null;
function postalLocation(code){
 const postal=String(code).trim().padStart(3,'0');
 const p=postals.find(p=>String(p.code)===postal);if(!p)return null;
 const saved=postalCalibrations[postal];
 if(Array.isArray(saved)&&saved.length===2&&saved.every(Number.isFinite))return saved;
 return worldToMap(p.x,p.y);
}
const calibrationButton=document.createElement('button');
calibrationButton.id='postalCalibrateBtn';calibrationButton.type='button';
calibrationButton.title='Fine-tune this postal by clicking its printed number on the satellite image';
calibrationButton.innerHTML='<i class="fa-solid fa-crosshairs"></i> Calibrate';
$('postalPinBtn').after(calibrationButton);
calibrationButton.onclick=()=>{
 const postal=String($('postalInput').value).trim().padStart(3,'0');
 if(!postals.some(p=>String(p.code)===postal))return toast('Enter a valid postal first.');
 calibratingPostal=postal;calibrationButton.classList.add('calibration-active');
 toast('Calibration: click the printed '+postal+' number on the map. Press Esc to cancel.');
};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&placementMode){placementMode=false;toast('Pin placement cancelled.');}if(e.key==='Escape'&&calibratingPostal){calibratingPostal=null;calibrationButton.classList.remove('calibration-active');toast('Calibration cancelled.')}});
map.on('click',e=>{
 if(!calibratingPostal)return;
 const postal=calibratingPostal;calibratingPostal=null;calibrationButton.classList.remove('calibration-active');
 postalCalibrations[postal]=[e.latlng.lat,e.latlng.lng];
 try{localStorage.setItem(POSTAL_CALIBRATION_KEY,JSON.stringify(postalCalibrations))}catch{return toast('Could not save postal calibration in this browser.');}
 // Prevent this click from also placing an investigation/general pin.
 if(e.originalEvent)e.originalEvent._efCalibrationClick=true;
 showPostalPopup(postalCalibrations[postal],postal);
 toast('Postal '+postal+' aligned to the map image and saved in this browser.');
});
function nearestPostal(ll){let best='',dist=Infinity;for(const p of postals){const [lat,lng]=postalLocation(p.code),d=(lat-ll.lat)**2+(lng-ll.lng)**2;if(d<dist){best=p.code;dist=d}}return best}
let postalMarker=null;
function showPostalPopup(pt,postal){if(postalMarker)map.removeLayer(postalMarker);postalMarker=L.marker(pt,{icon:L.divIcon({className:'postal-search-marker',html:'<div class="postal-dot"><i class="fa-solid fa-location-dot"></i></div>',iconSize:[36,44],iconAnchor:[18,40]})}).addTo(map);postalMarker.bindPopup('<div class="postal-popup-content"><span>POSTAL</span><strong>'+safe(postal)+'</strong></div>',{className:'postal-themed-popup',offset:[0,-32],closeButton:true,autoPan:true}).openPopup()}
$('postalSearchBtn').onclick=()=>{const pt=postalLocation($('postalInput').value);if(!pt)return toast('Postal not found.');if(postalMarker){map.removeLayer(postalMarker);postalMarker=null;}map.setView(pt,1.8,{animate:false});toast('Showing area around postal '+$('postalInput').value.trim().padStart(3,'0'))};
$('postalInput').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('postalSearchBtn').click()}});
$('postalPinBtn').onclick=()=>{placementMode=true;pinKind='general';placingForId=null;toast('Click the exact location on the map to create your pin. Press Esc to cancel.');};
$('customPinBtn').onclick=()=>{pinKind='general';placementMode=true;placingForId=null;toast('Click the exact location on the map to create your pin. Press Esc to cancel.');};
const markerLayer=L.layerGroup().addTo(map);
// Screenshot-derived, approximate reference locations. Independent of browser-saved cases.

// Hide investigation/location markers at wide map zoom levels to reduce clutter.
const PIN_MIN_VISIBLE_ZOOM=0.5;
map.on('zoomend',()=>render());
function markerSvgGlyph(name,color='#ffffff'){
 const d=window.EF_PIN_SVGS?.[name]||window.EF_PIN_SVGS?.['shield-halved'];
 if(!d)return '';
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${d[0]}"><path fill="${color}" d="${d[1]}"/></svg>`;
 return `<img class="ef-icon-image" src="data:image/svg+xml,${encodeURIComponent(svg)}" alt="" draggable="false">`;
}
// Compose the outline and the selected glyph into ONE image so legacy SVG
// and marker CSS cannot hide or stretch the inner icon.
// Every map marker uses the same permanent teardrop. Only its inner art changes.
// The outer shape and anchor are identical for icons, uploaded images and emojis.
function permanentPinSvg(c){
 const color=/^#[0-9a-fA-F]{6}$/.test(c.markerColor||'')?c.markerColor:'#348dff';
 const symbol=String(c.markerSymbol||'shield-halved');
 const d=window.EF_PIN_SVGS?.[symbol];
 const expanded=window.EF_EXPANDED_PIN_PACK?.find(x=>x.icon===symbol);
 let inner='';
 if(c.markerType==='image'&&/^data:image\/(png|jpeg|webp);base64,[a-z0-9+/=]+$/i.test(c.markerImage||'')){
   inner=`<image x="12" y="10" width="24" height="24" preserveAspectRatio="xMidYMid meet" href="${c.markerImage}"/>`;
 }else if(c.markerType==='emoji'){
   const emoji=String(c.markerEmoji||'📍').replace(/[<>&"']/g,'');
   inner=`<text x="24" y="29" font-size="21" text-anchor="middle">${emoji}</text>`;
 }else if(d){
   inner=`<svg x="12" y="9" width="24" height="25" viewBox="${d[0]}" preserveAspectRatio="xMidYMid meet"><path fill="#ffffff" d="${d[1]}"/></svg>`;
 }else if(expanded){
   inner=`<text x="24" y="29" font-size="21" text-anchor="middle">${expanded.emoji.replace(/[<>&"']/g,'')}</text>`;
 }else{
   const fallback=window.EF_PIN_SVGS?.['shield-halved'];
   if(fallback)inner=`<svg x="12" y="9" width="24" height="25" viewBox="${fallback[0]}"><path fill="#ffffff" d="${fallback[1]}"/></svg>`;
 }
 return `<svg xmlns="http://www.w3.org/2000/svg" width="48" height="56" viewBox="0 0 48 56"><path d="M24 2 C11 2 3 11 3 23 C3 37 17 46 24 54 C31 46 45 37 45 23 C45 11 37 2 24 2 Z" fill="${color}" stroke="#071322" stroke-width="3"/><path d="M24 6 C13 6 7 13 7 23 C7 33 16 42 24 49 C32 42 41 33 41 23 C41 13 35 6 24 6 Z" fill="#071526" fill-opacity=".88"/>${inner}</svg>`;
}
function permanentPinSrc(c){return 'data:image/svg+xml,'+encodeURIComponent(permanentPinSvg(c));}
function markerIcon(c,isSelected=false){
 const size=Math.max(26,Math.min(80,Number(c.markerSize)||42));
 const height=Math.round(size*56/48);
 return L.divIcon({className:'custom-marker ef-composed-marker',html:`<img class="ef-composed-pin" src="${permanentPinSrc(c)}" width="${size}" height="${height}" alt="" draggable="false">`,iconSize:[size,height],iconAnchor:[size/2,height-2],popupAnchor:[0,-height+6]});
}
function displayMarkerCategory(c){const cat=String(c.markerCategory||'').trim();return c.kind==='general'&&(!cat||cat==='Active Investigation')?'General Location':(cat|| (c.kind==='general'?'General Location':'Investigation'))}
function mapType(c){const cat=String(displayMarkerCategory(c)).toLowerCase();if(cat.includes('gang')||cat.includes('territory'))return 'gang';if(cat==='business'||cat.includes('business'))return 'business';if(cat.includes('police')||cat.includes('pd station')||cat.includes('government'))return 'pd';if(c.kind!=='general'||cat.includes('detective')||cat.includes('investigation')||cat.includes('crime scene')||cat.includes('evidence')||(cat.includes('person of interest')||cat.includes('location of interest'))||cat.includes('resolved'))return 'detective';return 'other'}
function enabledMapTypes(){return new Set([...document.querySelectorAll('#mapTypeFilters input[data-maptype]:checked')].map(x=>x.dataset.maptype))}
document.querySelectorAll('#mapTypeFilters input[data-maptype]').forEach(el=>el.addEventListener('change',render));$('showAllTypes').onclick=()=>{document.querySelectorAll('#mapTypeFilters input[data-maptype]').forEach(el=>el.checked=true);render()};
function filteredCases(){const q=$('searchInput').value.toLowerCase(),s=$('categoryFilter').value,o=$('officerFilter').value.toLowerCase(),mc=$('markerCategoryFilter')?.value||'all';return cases.filter(c=>(mc==='all'||c.markerCategory===mc)&&(s==='all'||c.kind==='general'||c.status===s)&&(!o||String(c.detective).toLowerCase().includes(o))&&(!q||[c.caseNo,c.location,c.detective,c.suspect,c.notes,c.markerCategory].join(' ').toLowerCase().includes(q)))}
