function renderExtra(section){if(section==='poi'||section==='warrants'){renderIntelligence(section);return;}$('extraTitle').textContent=sectionNames[section]||section.toUpperCase();$('addEntryBtn').style.display=['settings','search'].includes(section)?'none':'';if(section==='settings'){$('extraContent').innerHTML='<div class="db-card"><h3>LOCAL PREVIEW MODE</h3><p>Cases, marker images and database entries are saved only in this browser. They are not shared or protected by detective logins.</p><p>To enable secure accounts, permissions and shared uploads, a hosted backend is needed.</p><button id="exportBtn">Export Local Data (JSON)</button></div>';$('exportBtn').onclick=()=>{const blob=new Blob([JSON.stringify({cases,iconLibrary,database},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='EverFallLspdDb-backup.json';a.click();URL.revokeObjectURL(a.href)};$('extraContent').insertAdjacentHTML('beforeend',`<div class="db-card"><h3>NAVIGATION</h3><label class="history-settings-label"><input id="historyVisibilitySetting" type="checkbox"> Show History tab in bottom navigation</label><p>History remains available from Settings when hidden. Your saved history is not deleted.</p><button id="openHistorySettings" type="button">Open History</button></div>`);$('historyVisibilitySetting').checked=localStorage.getItem('eflspddb_show_history_tab')==='true';$('historyVisibilitySetting').onchange=e=>{localStorage.setItem('eflspddb_show_history_tab',String(e.target.checked));syncHistoryTab()};$('openHistorySettings').onclick=()=>showSection('history');$('extraContent').insertAdjacentHTML('beforeend',`<div class="db-card"><h3>OWNER CLEANUP</h3><p>Delete test pins and cases from this browser. Locked markers must be unlocked first.</p><button id="cleanupPins">Manage all markers</button><button id="clearSamples">Remove sample cases</button><button id="changeCode">Change local access code</button></div>`);$('cleanupPins').onclick=()=>showSection('cases');$('clearSamples').onclick=()=>{if(!confirm('Remove the two original sample cases?'))return;cases=cases.filter(c=>!['EF-26-014','EF-26-011'].includes(c.id));saveCases();render();toast('Sample cases removed.')};$('changeCode').onclick=()=>{const old=prompt('Enter current access code:');if(old!==localStorage.getItem('everfall_access_code_v1'))return toast('Incorrect code.');const next=prompt('New access code (at least 4 characters):');if(next&&next.length>=4){localStorage.setItem('everfall_access_code_v1',next);toast('Local code changed.')}};return}if(section==='search'){$('extraContent').innerHTML='<div class="db-card"><input id="globalSearch" placeholder="Search all cases and database entries..." style="width:100%;padding:12px;background:#06162b;color:white;border:1px solid #38638d"><div id="globalResults"></div></div>';$('globalSearch').oninput=e=>{const q=e.target.value.toLowerCase();$('globalResults').innerHTML=q?cases.filter(c=>JSON.stringify(c).toLowerCase().includes(q)).map(c=>`<div class="mini-item"><button data-findcase="${safe(c.id)}">${safe(c.caseNo)}</button> — ${safe(c.location)}</div>`).join('')+Object.entries(database).flatMap(([s,rows])=>rows.filter(r=>JSON.stringify(r).toLowerCase().includes(q)).map(r=>`<div class="mini-item">${safe(s)}: ${safe(r.title)}</div>`)).join(''):''};$('globalResults').onclick=e=>{const b=e.target.closest('[data-findcase]');if(b)selectCase(b.dataset.findcase)};return}if(section==='reports'){$('extraContent').innerHTML='<div class="db-card"><h3>CASE REPORTS</h3><p>Create an investigation case, then open it from the Cases section to edit its notes and linked information.</p><button id="newReport">+ Create Case</button></div>';$('newReport').onclick=()=>openModal();return}const rows=database[section]||[];$('extraContent').innerHTML=`<p style="color:#91b9df">Local intelligence records. Add a record and link it to a case using its case number.</p>${rows.length?rows.map((r,i)=>`<div class="db-card"><h3>${safe(r.title)}</h3><p>${safe(r.description)}</p><small>Linked Case: ${safe(r.caseNo||'None')} · ${fmtDate(r.updated)}</small><br><button data-dbedit="${i}">Edit</button><button data-dbdelete="${i}">Delete</button></div>`).join(''):'<div class="db-card">No records added yet.</div>'}`;$('extraContent').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.dbedit!==undefined)addEntry(section,Number(b.dataset.dbedit));if(b.dataset.dbdelete!==undefined&&confirm('Delete this record?')){database[section].splice(Number(b.dataset.dbdelete),1);saveDb();renderExtra(section)}}}
function addEntry(section,index=null){if(['search','settings'].includes(section))return;if(section==='poi'||section==='warrants'){editIntelligence(section,index);return;}const existing=index!==null?database[section]?.[index]:null;const title=prompt('Record title / name:',existing?.title||'');if(title===null||!title.trim())return;const description=prompt('Details / roster / notes:',existing?.description||'');if(description===null)return;const caseNo=prompt('Linked case number (optional):',existing?.caseNo||'');if(caseNo===null)return;database[section]??=[];const entry={title:title.trim(),description,caseNo:caseNo.trim(),updated:new Date().toISOString()};if(index!==null)database[section][index]=entry;else database[section].push(entry);saveDb();renderExtra(section);toast('Record saved locally.')}

// Dedicated local intelligence records. Names and case numbers are links, not identity verification.
const intelFields={
 poi:[['title','Full name','text'],['aliases','Aliases','text'],['photo','Photo URL (optional)','url'],['gang','Gang / affiliation','text'],['associates','Known associates','text'],['vehicles','Known vehicles / plates','text'],['addresses','Known addresses','text'],['caseNo','Linked case number(s), comma-separated','text'],['notes','Intelligence notes','textarea']],
 warrants:[['title','Warrant number','text'],['subject','Subject / person','text'],['offences','Offences / grounds','text'],['issued','Date issued','date'],['expires','Expiry date','date'],['detective','Assigned detective','text'],['status','Status','select'],['caseNo','Linked case number(s), comma-separated','text'],['notes','Warrant notes','textarea']]
};
function intelLinkedNumbers(value){return String(value||'').split(',').map(v=>v.trim().toLowerCase()).filter(Boolean)}
function linkedCaseRows(value){const nums=intelLinkedNumbers(value);return cases.filter(c=>nums.includes(String(c.caseNo).toLowerCase()));}
function renderIntelligence(section){
 $('extraTitle').textContent=sectionNames[section];$('addEntryBtn').style.display='';
 const rows=database[section]||[];
 $('extraContent').innerHTML=`<p class="intel-hint">${section==='poi'?'Person profiles can link to cases, vehicles, gang records and warrants.':'Warrants are records for this roleplay database; update their status as they progress.'} Data is saved only in this browser.</p><div class="intel-search"><input id="intelSearch" placeholder="Search ${section==='poi'?'people, aliases, gangs':'warrant numbers, subjects, status'}..." aria-label="Search records"><select id="intelStatus" ${section==='poi'?'hidden':''}><option value="">All statuses</option>${['Pending','Active','Served','Expired','Cancelled'].map(x=>`<option>${x}</option>`).join('')}</select></div><div id="intelList"></div>`;
 const paint=()=>{const q=($('intelSearch').value||'').toLowerCase(),status=$('intelStatus').value;
 $('intelList').innerHTML=rows.map((r,i)=>({r,i})).filter(({r})=>(!q||JSON.stringify(r).toLowerCase().includes(q))&&(!status||r.status===status)).map(({r,i})=>{
 const related=section==='poi'?(database.warrants||[]).filter(w=>String(w.subject||'').trim().toLowerCase()===String(r.title||'').trim().toLowerCase()):[];
 const caseRows=linkedCaseRows(r.caseNo);
 const veh=(database.vehicles||[]).filter(v=>JSON.stringify(v).toLowerCase().includes(String(r.title||'').toLowerCase())&&r.title);
 const gang=(database.gangs||[]).filter(v=>r.gang&&JSON.stringify(v).toLowerCase().includes(String(r.gang).toLowerCase()));
 return `<article class="db-card intel-card"><div class="intel-cardhead"><div><h3>${safe(r.title)}</h3><small>${section==='warrants'?`<span class="intel-status ${safe(r.status||'Pending')}">${safe(r.status||'Pending')}</span> · ${safe(r.subject||'No subject')}`:safe(r.aliases?'Also known as: '+r.aliases:'Person of Interest')}</small></div><div><button data-intel-edit="${i}">Edit</button><button data-intel-delete="${i}">Delete</button></div></div>${section==='poi'&&r.photo?`<img class="intel-photo" src="${safe(r.photo)}" alt="POI photo" loading="lazy" referrerpolicy="no-referrer">`:''}<div class="intel-details">${(section==='poi'?[['Gang / Affiliation',r.gang],['Known Associates',r.associates],['Vehicles / Plates',r.vehicles],['Addresses',r.addresses]]:[['Offences',r.offences],['Issued',r.issued],['Expires',r.expires],['Detective',r.detective]]).filter(x=>x[1]).map(x=>`<div><b>${safe(x[0])}</b><span>${safe(x[1])}</span></div>`).join('')}</div>${r.notes?`<p>${safe(r.notes)}</p>`:''}<div class="intel-links"><strong>LINKED RECORDS</strong><div>${caseRows.length?caseRows.map(c=>`<button data-intel-case="${safe(c.id)}">Case ${safe(c.caseNo)}</button>`).join(''):'<span>No matching linked cases</span>'}</div>${section==='poi'?`<div>${related.length?related.map(w=>`<button data-intel-warrant="${safe(w.title)}">Warrant ${safe(w.title)} (${safe(w.status||'Pending')})</button>`).join(''):'<span>No linked warrants</span>'}</div><div>${veh.length?`Vehicles: ${veh.map(v=>safe(v.title)).join(', ')}`:'No linked vehicle records'}</div><div>${gang.length?`Gangs: ${gang.map(v=>safe(v.title)).join(', ')}`:'No linked gang records'}</div>`:''}</div><small>Updated ${fmtDate(r.updated)}</small></article>`}).join('')||'<div class="db-card">No matching records yet. Click Add Entry to create one.</div>';
 };
 $('intelSearch').oninput=paint;$('intelStatus').onchange=paint;paint();
 $('intelList').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.intelEdit!==undefined)editIntelligence(section,Number(b.dataset.intelEdit));if(b.dataset.intelDelete!==undefined&&confirm('Delete this record?')){database[section].splice(Number(b.dataset.intelDelete),1);saveDb();renderIntelligence(section)}if(b.dataset.intelCase)selectCase(b.dataset.intelCase);if(b.dataset.intelWarrant){showSection('warrants');$('intelSearch').value=b.dataset.intelWarrant;$('intelSearch').dispatchEvent(new Event('input'))}};
}
function editIntelligence(section,index=null){
 const existing=index===null?{}:database[section]?.[index]||{};
 const form=document.createElement('form');form.className='db-card intel-form';
 form.innerHTML=`<h3>${index===null?'NEW':'EDIT'} ${section==='poi'?'PERSON OF INTEREST':'WARRANT'}</h3><div class="intel-formgrid">${intelFields[section].map(([key,label,type])=>`<label>${safe(label)}${type==='textarea'?`<textarea name="${key}" rows="3">${safe(existing[key]||'')}</textarea>`:type==='select'?`<select name="${key}">${['Pending','Active','Served','Expired','Cancelled'].map(v=>`<option ${existing[key]===v?'selected':''}>${v}</option>`).join('')}</select>`:`<input name="${key}" type="${type}" value="${safe(existing[key]||'')}" ${key==='title'?'required maxlength="120"':'maxlength="500"'}>`}</label>`).join('')}</div><div class="intel-actions"><button class="blue" type="submit">Save Record</button><button type="button" id="intelCancel">Cancel</button></div>`;
 $('extraContent').prepend(form);form.scrollIntoView({block:'start',behavior:'smooth'});form.querySelector('#intelCancel').onclick=()=>form.remove();
 form.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form).entries());data.title=data.title.trim();if(!data.title)return;data.updated=new Date().toISOString();database[section]??=[];if(index===null)database[section].push(data);else database[section][index]=data;saveDb();renderIntelligence(section);toast('Record saved in this browser.')};
}

$('addEntryBtn').onclick=()=>addEntry(currentSection);
function tick(){const d=new Date();$('clockTime').textContent=d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});$('clockDate').textContent=d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}tick();setInterval(tick,30000);render();




// Side panels: toggle visibility without changing map coordinates or zoom.
(function(){
 const workspace=document.querySelector('.workspace');
 if(!workspace)return;
 function setup(buttonId,cssClass,iconExpanded,iconCollapsed,label){
  const button=document.getElementById(buttonId);
  if(!button)return;
  button.addEventListener('click',e=>{
   e.preventDefault();e.stopPropagation();
   const collapsed=workspace.classList.toggle(cssClass);
   button.innerHTML='<i class="fa-solid fa-'+(collapsed?iconCollapsed:iconExpanded)+'"></i>';
   button.setAttribute('aria-label',(collapsed?'Expand ':'Collapse ')+label);
   button.title=(collapsed?'Expand ':'Collapse ')+label;
   button.setAttribute('aria-expanded',String(!collapsed));
   if(typeof map!=='undefined'&&map.invalidateSize){map.invalidateSize({pan:false});setTimeout(()=>map.invalidateSize({pan:false}),80);}
  });
 }
 setup('toggleLeftPanel','left-collapsed','angles-left','angles-right','map controls');
 setup('toggleRightPanel','right-collapsed','angles-right','angles-left','case overview');
})();


