const MARKER_ICON_OPTIONS=[['shield-halved','Police'],['magnifying-glass','Search'],['skull','Crime'],['fingerprint','Evidence'],['car','Vehicle'],['users','Gang'],['triangle-exclamation','Warning'],['shield-halved','Police Station'],['user-secret','Detective'],['lock','Prison'],['plane','Airport'],['hospital','Hospital'],['wrench','Mechanic'],['building-columns','Bank'],['flag-checkered','Race Track'],['dice','Casino'],['gas-pump','Gas Station'],['fire-flame-curved','Fire Station'],['bell','Emergency'],['link','Arrest'],['tower-broadcast','Dispatch'],['shield','Raid'],['truck-medical','EMS'],['fire-extinguisher','Fire'],['helicopter','Helicopter'],['ship','Marine'],['folder-open','Case File'],['address-card','Suspect'],['eye','Surveillance'],['camera','CCTV'],['crosshairs','Shooting'],['shoe-prints','Footprints'],['box-open','Seized Item'],['file-circle-exclamation','Warrant'],['skull-crossbones','Homicide'],['hand-fist','Violence'],['car-burst','Stolen Vehicle'],['fire','Arson'],['house','Safehouse'],['warehouse','Warehouse'],['biohazard','Drugs'],['flag','Territory'],['store','Shop'],['utensils','Restaurant'],['martini-glass','Bar'],['hotel','Hotel'],['house-chimney','Property'],['square-parking','Parking'],['anchor','Docks'],['train','Train Station'],['cannabis','Cannabis Property'],['sack-dollar','Business'],['car-side','Dealership'],['square-xmark','Fuel Station'],['square-parking','Garage'],['gun','Gun Shop'],['building','Apartment'],['house-chimney-user','Residential Property'],['star-of-life','Medical Centre'],['scissors','Barber Shop'],['recycle','Bottle Bank'],['bowling-ball','Bowling'],['shirt','Clothing Shop'],['id-card','Licensing'],['gem','Diamond Casino'],['fire-flame-simple','Furnace']];
const MARKER_COLOURS=['#ef5266','#f7c847','#47a8f4','#5ccf8b','#b8c8e3'];
const MARKER_GROUPS=[['All',0,1000],['Police & Investigation',0,10],['FiveM Locations',10,19],['Emergency',19,27],['Evidence',27,35],['Crime & Gangs',35,43],['Places',43,51],['Server Blips',51,1000]];
let markerGroup='All';
function refreshIconPalette(){const f=$('caseForm');if(!f)return;const color=f.elements.markerColor.value,symbol=f.elements.markerSymbol.value;const colours=$('markerColourChoices'),icons=$('markerIconChoices');if(!colours||!icons)return;
colours.innerHTML=MARKER_COLOURS.map(c=>`<button type="button" class="palette-colour ${color.toLowerCase()===c?'selected':''}" data-colour="${c}" aria-label="Select ${c} colour" title="${c}"><span style="background:${c}"></span></button>`).join('');
const cats=$('pickerCategories');if(cats)cats.innerHTML=MARKER_GROUPS.map(([name])=>`<button type="button" class="picker-category ${markerGroup===name?'active':''}" data-group="${name}">${name}</button>`).join('');
const q=($('markerIconSearch')?.value||'').trim().toLowerCase();const group=MARKER_GROUPS.find(g=>g[0]===markerGroup)||MARKER_GROUPS[0];const visible=MARKER_ICON_OPTIONS.filter(([name,label],idx)=>(q||idx>=group[1]&&idx<group[2])&&(!q||`${label} ${name}`.toLowerCase().includes(q)));
icons.innerHTML=visible.map(([name,label])=>`<button type="button" class="palette-icon ${symbol===name?'selected':''}" data-icon="${name}" title="${label}" aria-pressed="${symbol===name}"><i class="fa-solid fa-${name}" style="color:${safe(color)}"></i>${symbol===name?'<b class="picker-check"><i class="fa-solid fa-check"></i></b>':''}</button>`).join('');
const count=$('pickerIconCount');if(count)count.textContent=`${visible.length} of ${MARKER_ICON_OPTIONS.length}`;const result=$('pickerResultsLabel');if(result)result.textContent=q?`Results for “${q}”`:markerGroup;const empty=$('pickerNoResults');if(empty)empty.hidden=!!visible.length;
const live=$('pickerLiveIcon');if(live)live.innerHTML=`<i class="fa-solid fa-${symbol}" style="color:${safe(color)}"></i>`;const label=$('pickerLiveLabel');if(label)label.textContent=MARKER_ICON_OPTIONS.find(x=>x[0]===symbol)?.[1]||'Custom';
}
$('pickerCategories')?.addEventListener('click',e=>{const b=e.target.closest('[data-group]');if(!b)return;markerGroup=b.dataset.group;refreshIconPalette()});
$('markerColourChoices')?.addEventListener('click',e=>{const b=e.target.closest('[data-colour]');if(!b)return;const f=$('caseForm');f.elements.markerColor.value=b.dataset.colour;f.elements.markerType.value='symbol';updatePreview()});
$('markerIconChoices')?.addEventListener('click',e=>{const b=e.target.closest('[data-icon]');if(!b)return;const f=$('caseForm');f.elements.markerSymbol.value=b.dataset.icon;f.elements.markerType.value='symbol';updatePreview()});

$('markerIconSearch')?.addEventListener('input',refreshIconPalette);

