(()=>{
const KEY='eflspddb_investigation_files_v1', RKEY='eflspddb_detective_roster_v1';
const get=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};
let files=get(KEY,[]),roster=get(RKEY,[]),editing=null,photos=[],videoLinks=[],linked=[];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','"':'&quot;',"'":'&#39;'}[c]));
const store=()=>{try{localStorage.setItem(KEY,JSON.stringify(files));localStorage.setItem(RKEY,JSON.stringify(roster));window.EF8H?.onLocalSave?.(files);return true}catch{alert('Browser storage is full. Reduce the size of uploaded photos or export your data.');return false}};
const oldRenderRecords=renderRecords;
const oldRenderExtra=renderExtra;
const oldShowSection=showSection;
const oldAddEntry=addEntry;
const recordSection=document.getElementById('recordsView');
recordSection.insertAdjacentHTML('afterbegin','<div class="case-toolbar"><input id="caseFileSearch" placeholder="Search cases, suspects, detectives..." aria-label="Search case files"><select id="caseFileFilter"><option value="">All statuses</option><option>Active</option><option>Pending</option><option>Closed</option><option>Cold Case</option></select><button id="manageDetectives" type="button">Manage Detectives</button></div>');
document.body.insertAdjacentHTML('beforeend','<div id="caseEditor" class="ef-overlay hidden"><div class="ef-dialog"><div class="ef-dialog-head"><h2 id="caseEditorTitle">New Investigation Case</h2><button type="button" id="closeCaseEditor">✕</button></div><form id="caseFileForm"><div class="ef-formgrid"><label>Case Number<input name="number" required placeholder="DB-2026-001"></label><label>Status<select name="status"><option>Active</option><option>Pending</option><option>Closed</option><option>Cold Case</option></select></label><label class="wide">Case Title<input name="title" required placeholder="Operation Nightfall"></label><label>Assigned Detective<select name="detective" id="caseDetectiveSelect"></select></label><label>Location / Postal<input name="location" placeholder="Mirror Park / 568"></label><label class="wide">Linked Gang / Roster<select name="gang" id="caseGangSelect"><option value="">None</option></select></label><label class="wide">Suspect / Gang<input name="suspect" placeholder="Name, gang, known associates"></label><label class="wide">Investigation Summary<textarea name="description" rows="4"></textarea></label></div><h3>Linked Map Pins</h3><p class="ef-hint">Choose any existing manual pins. These remain separate map locations.</p><div id="caseLinkedPins" class="ef-checklist"></div><h3>Photos</h3><label class="ef-upload">+ Add Photos <input id="casePhotos" type="file" accept="image/png,image/jpeg,image/webp" multiple></label><div id="casePhotoGallery" class="ef-photos"></div><h3>Video Evidence Links</h3><div class="ef-inline"><input id="caseVideoInput" type="url" placeholder="https://youtube.com/... or Streamable URL"><button id="caseAddVideo" type="button">+ Add Link</button></div><div id="caseVideos"></div><div class="ef-actions"><button type="button" id="deleteCaseFile" class="ef-case-delete">Delete Case</button><button type="button" id="cancelCase">Cancel</button><button class="blue" type="submit">Save Case</button></div></form></div></div>');
function refreshLinked(){document.getElementById('caseLinkedPins').innerHTML=cases.filter(c=>typeof c.lat==='number'&&typeof c.lng==='number').map(c=>`<label><input type="checkbox" value="${esc(c.id)}" ${linked.includes(c.id)?'checked':''}> ${esc(c.caseNo)} <small>${esc(c.location)}</small></label>`).join('')||'<p class="ef-hint">No placed pins yet. Add pins on the map first.</p>'}
function refreshPhotos(){document.getElementById('casePhotoGallery').innerHTML=photos.map((p,i)=>`<div class="ef-photo"><img src="${p.data}" alt="${esc(p.name)}"><small>${esc(p.name)}</small><button type="button" data-removephoto="${i}">✕</button></div>`).join('')}
function refreshVideos(){document.getElementById('caseVideos').innerHTML=videoLinks.map((v,i)=>`<div class="ef-video"><a href="${esc(v)}" target="_blank" rel="noopener noreferrer">${esc(v)}</a><button type="button" data-removevideo="${i}">Remove</button></div>`).join('')}
function openEditor(f=null){editing=f?.id||null;document.getElementById('deleteCaseFile').hidden=!f;photos=[...(f?.photos||[])];videoLinks=[...(f?.videos||[])];linked=[...(f?.linked||[])];const form=document.getElementById('caseFileForm');form.reset();for(const k of ['number','title','status','detective','location','suspect','description'])if(f?.[k]!==undefined&&form.elements[k])form.elements[k].value=f[k];document.getElementById('caseEditorTitle').textContent=f?'Edit Investigation Case':'New Investigation Case';const ds=document.getElementById('caseDetectiveSelect');ds.innerHTML='<option value="Unassigned">Unassigned</option>'+roster.map(d=>`<option value="${esc(d)}">${esc(d)}</option>`).join('');ds.value=f?.detective||'Unassigned';const gs=document.getElementById('caseGangSelect');gs.innerHTML='<option value="">None</option>'+(database.gangs||[]).map((g,i)=>`<option value="${esc(g.title)}">${esc(g.title)}</option>`).join('');gs.value=f?.gang||'';refreshLinked();refreshPhotos();refreshVideos();document.getElementById('caseEditor').classList.remove('hidden')}
function closeEditor(){document.getElementById('caseEditor').classList.add('hidden')}
document.getElementById('deleteCaseFile').onclick=()=>{
 if(!editing)return;
 const f=files.find(x=>x.id===editing);if(!f)return;
 if(!confirm('Delete case '+f.number+'? Linked map pins will be kept. This case file will be removed from this browser.'))return;
 const previous=[...files];files=files.filter(x=>x.id!==editing);
 window.EF8H?.onLocalDelete?.(editing);
 if(!store()){files=previous;return}
 closeEditor();renderRecords();render();
};
document.getElementById('closeCaseEditor').onclick=closeEditor;document.getElementById('cancelCase').onclick=closeEditor;
document.getElementById('caseEditor').addEventListener('click',e=>{if(e.target.id==='caseEditor')closeEditor()});
document.getElementById('casePhotos').onchange=async e=>{for(const file of [...e.target.files]){if(file.size>250000){alert(`${file.name}: Maximum 250 KB per photo for browser-only storage.`);continue}const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});photos.push({name:file.name,data})}refreshPhotos();e.target.value=''};
document.getElementById('casePhotoGallery').onclick=e=>{const b=e.target.closest('[data-removephoto]');if(b){photos.splice(+b.dataset.removephoto,1);refreshPhotos()}};
document.getElementById('caseAddVideo').onclick=()=>{const el=document.getElementById('caseVideoInput');try{const u=new URL(el.value);if(!['http:','https:'].includes(u.protocol))throw Error();videoLinks.push(u.href);el.value='';refreshVideos()}catch{alert('Enter a valid http or https video link.')}};
document.getElementById('caseVideos').onclick=e=>{const b=e.target.closest('[data-removevideo]');if(b){videoLinks.splice(+b.dataset.removevideo,1);refreshVideos()}};
document.getElementById('caseFileForm').onsubmit=e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f).entries());if(files.some(c=>c.number.toLowerCase()===d.number.trim().toLowerCase()&&c.id!==editing))return alert('Case number already exists.');const obj={id:editing||('case-'+Date.now()),number:d.number.trim(),title:d.title.trim(),status:d.status,detective:d.detective,location:d.location,suspect:d.suspect,gang:d.gang,description:d.description,photos:[...photos],videos:[...videoLinks],linked:[...document.querySelectorAll('#caseLinkedPins input:checked')].map(x=>x.value),updated:new Date().toISOString()};const prev=[...files];if(editing)files=files.map(x=>x.id===editing?obj:x);else files.unshift(obj);if(!store()){files=prev;return}closeEditor();renderRecords();render()};
window.EFCaseFiles={list:()=>files.map(f=>({...f})),open:id=>openEditor(files.find(f=>f.id===id)),create:()=>openEditor(),setRoster:names=>{roster=[...new Set(names.filter(Boolean))];store()},getRoster:()=>[...roster]};
window.EF8H3RemoveCase=function(id){const i=files.findIndex(x=>x.id===id);if(i<0)return true;files.splice(i,1);localStorage.setItem(KEY,JSON.stringify(files));renderRecords();render();return true};
window.EF8HApplyRemoteCase=function(record){if(!record||typeof record.id!=='string')return false;const i=files.findIndex(x=>x.id===record.id);if(i>=0)files[i]=record;else files.unshift(record);try{localStorage.setItem(KEY,JSON.stringify(files));renderRecords();render();return true}catch{return false}};
document.getElementById('manageDetectives').onclick=()=>window.EFManageDetectives?.();
document.getElementById('caseFileSearch').oninput=()=>renderRecords();
document.getElementById('caseFileFilter').onchange=()=>renderRecords();
renderRecords=function(){const q=document.getElementById('caseFileSearch').value.trim().toLowerCase(),status=document.getElementById('caseFileFilter').value;const shown=files.filter(f=>(!status||f.status===status)&&(!q||[f.number,f.title,f.suspect,f.detective,f.location].join(' ').toLowerCase().includes(q)));document.getElementById('recordsBody').innerHTML=shown.length?shown.map(f=>`<tr><td><button type="button" class="ef-case-number-btn" data-fileopen="${esc(f.id)}" title="Open ${esc(f.number)}"><strong>${esc(f.number)}</strong><span>${esc(f.title)}</span></button></td><td>${f.location?`<button type="button" class="ef-postal-jump" data-filepostal="${esc(f.id)}" title="Show this location on the map"><i class="fa-solid fa-location-dot" aria-hidden="true"></i> ${esc(f.location)}</button>`:'—'}</td><td>${esc(f.detective||'Unassigned')}</td><td><span class="status-tag">${esc(f.status)}</span></td><td>${new Date(f.updated).toLocaleDateString('en-GB')}</td><td><button data-fileopen="${esc(f.id)}">Edit</button> <button data-filemap="${esc(f.id)}">Map (${f.linked.length})</button> <button data-filedelete="${esc(f.id)}">Delete</button></td></tr>`).join(''):'<tr><td colspan="6">No investigation case files yet. Click + New Case to begin. Existing map pins are not cases.</td></tr>'};
document.getElementById('addRecordBtn').addEventListener('click',e=>{e.stopImmediatePropagation();openEditor()},true);
document.getElementById('recordsBody').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;e.stopImmediatePropagation();const id=b.dataset.fileopen||b.dataset.filemap||b.dataset.filepostal||b.dataset.filedelete;const f=files.find(x=>x.id===id);if(!f)return;if(b.dataset.filepostal){
 const placed=cases.find(x=>f.linked.includes(x.id)&&typeof x.lat==='number'&&typeof x.lng==='number');
 const match=String(f.location||'').match(/\b\d{3,4}\b/);
 const point=placed?[placed.lat,placed.lng]:(match?postalLocation(match[0]):null);
 if(!point){alert('No linked map pin or recognised postal found for this case. Link a pin in Edit to navigate to its exact position.');return}
 showSection('map');
 map.invalidateSize();
 map.setView(point,1.8,{animate:false});
 if(placed){selectedId=placed.id;renderDetail();}
 else {showPostalPopup(point,match[0]);}
 render();
 return;
 }if(b.dataset.fileopen)openEditor(f);if(b.dataset.filedelete&&confirm(`Delete ${f.number}? Pins will be kept.`)){files=files.filter(x=>x.id!==id);store();renderRecords();render()}if(b.dataset.filemap){const c=cases.find(x=>f.linked.includes(x.id));if(!c)return alert('This case has no linked placed pins.');oldShowSection('map');map.setView([c.lat,c.lng],Math.max(map.getZoom(),1.8));render()}},true);
const originalRender=render;
render=function(){originalRender();markerLayer.eachLayer(m=>{const p=m.getLatLng();const c=cases.find(x=>x.lat===p.lat&&x.lng===p.lng);if(!c)return;const associated=files.filter(f=>f.linked.includes(c.id));if(!associated.length)return;const f=associated[0];m.unbindTooltip();m.bindTooltip(`<div class="ef-case-bubble"><strong>${esc(f.number)}</strong><b>${esc(f.title)}</b><span>${esc(f.status)} · ${esc(f.detective||'Unassigned')}</span><span>${esc(f.location||c.location)}</span><small>${f.photos.length} photos · ${f.videos.length} videos · ${associated.length} linked case(s)</small></div>`,{direction:'top',offset:[0,-22],opacity:1,className:'case-map-tooltip'});m.off('click');m.on('click',()=>openEditor(f))})};

/* Contact intelligence directory */
const CONTACT_KEY='eflspddb_contacts_v1';
let contacts=get(CONTACT_KEY,[]), contactEditing=null, contactPhoto='';
window.efContacts={get:()=>contacts,save:()=>contactSave(),upsert:(entry)=>{const index=contacts.findIndex(c=>c.id===entry.id);if(index>=0)contacts[index]={...contacts[index],...entry};else contacts.unshift(entry);contactSave();if(currentSection==='contacts')renderContacts()},open:(id)=>openContact(id),refresh:()=>{if(currentSection==='contacts')renderContacts()}};
const contactSave=()=>{try{localStorage.setItem(CONTACT_KEY,JSON.stringify(contacts));window.EF8H2?.localChanged("contacts");return true}catch{alert('Contact storage is full. Use a smaller image.');return false}};
document.body.insertAdjacentHTML('beforeend',`<div class="ef-overlay hidden" id="contactEditor"><div class="ef-dialog"><div class="ef-dialog-head"><h2 id="contactHeading">Add Contact</h2><button type="button" id="contactClose">✕</button></div><form id="contactForm"><div class="ef-formgrid"><label>Full Name<input name="name" required></label><label>Known Alias<input name="alias"></label><label>Date of Birth<input name="dob" type="date"></label><label>Physical Description<input name="physical"></label><label>Known Vehicles<input name="vehicles"></label><label>Known Associates<input name="associates"></label><label>Phone Number<input name="phone"></label><label>Last Known Location<input name="location"></label><label>Associated Gang<select name="gang"><option value="">No Gang Affiliation</option></select></label><label class="wide">Linked Case Numbers<input name="cases" placeholder="DB-2026-001, DB-2026-002"></label><label class="wide">Contact Photo<input type="file" id="contactPhotoUpload" accept="image/png,image/jpeg,image/webp"></label><div id="contactPhotoPreview"></div><label class="wide">Intelligence Notes<textarea name="notes" rows="5"></textarea></label><label>Who Added<input name="addedBy" required placeholder="Detective name"></label><label>Date Last Contacted<input name="lastContact" type="date"></label></div><div class="ef-actions"><button type="button" id="contactCancel">Cancel</button><button type="submit" class="blue">Save Contact</button></div></form></div></div>`);
function openContact(id=null){contactEditing=id;const old=contacts.find(c=>c.id===id);const form=document.getElementById('contactForm');form.reset();form.elements.gang.innerHTML='<option value="">No Gang Affiliation</option>'+(database.gangs||[]).map(g=>`<option value="${esc(g.title)}">${esc(g.title)}</option>`).join('');contactPhoto=old?.photo||'';for(const key of ['name','type','alias','phone','location','gang','cases','notes','addedBy','lastContact','dob','physical','vehicles','associates'])if(old?.[key]!=null && form.elements.namedItem(key))form.elements.namedItem(key).value=old[key];document.getElementById('contactHeading').textContent=old?'Edit Contact':'Add Contact';document.getElementById('contactPhotoPreview').innerHTML=contactPhoto?`<img src="${contactPhoto}" alt="Contact" width="90">`:'';document.getElementById('contactEditor').classList.remove('hidden')}
function closeContact(){document.getElementById('contactEditor').classList.add('hidden')}
document.getElementById('contactClose').onclick=closeContact;document.getElementById('contactCancel').onclick=closeContact;
document.getElementById('contactPhotoUpload').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.size>250000)return alert('Contact photo maximum 250 KB.');const r=new FileReader();r.onload=()=>{contactPhoto=r.result;document.getElementById('contactPhotoPreview').innerHTML=`<img src="${contactPhoto}" alt="Contact" width="90">`};r.readAsDataURL(file)};
document.getElementById('contactForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());const item={id:contactEditing||'contact-'+Date.now(),name:d.name.trim(),type:contacts.find(c=>c.id===contactEditing)?.type||'Contact',alias:d.alias,phone:d.phone,location:d.location,gang:d.gang,cases:d.cases,notes:d.notes,addedBy:d.addedBy,lastContact:d.lastContact,dob:d.dob,physical:d.physical,vehicles:d.vehicles,associates:d.associates,affiliations:contacts.find(c=>c.id===contactEditing)?.affiliations||[],photo:contactPhoto,updated:new Date().toISOString()};const before=[...contacts];contacts=contactEditing?contacts.map(c=>c.id===contactEditing?item:c):[item,...contacts];if(!contactSave()){contacts=before;return}closeContact();window.efSyncContactToGangs?.(item);renderContacts()};
function renderContacts(){document.getElementById('extraTitle').textContent='CONTACT DIRECTORY';const add=document.getElementById('addEntryBtn');add.textContent='+ Add Contact';add.style.display='';const content=document.getElementById('extraContent');content.innerHTML=`<div class="ef-contact-tools"><input id="contactSearch" placeholder="Search name, alias, phone, location or gang..." aria-label="Search contacts"></div><div id="contactResults"></div><p class="ef-hint">Local browser-only intelligence directory. Do not enter real confidential informant information until secure accounts and shared storage are available.</p>`;const draw=()=>{const q=document.getElementById('contactSearch').value.toLowerCase(),visible=contacts.filter(c=>(!q||[c.name,c.alias,c.phone,c.location,c.gang,c.cases].join(' ').toLowerCase().includes(q)));document.getElementById('contactResults').innerHTML=visible.length?visible.map(c=>`<div class="ef-contact-card"><div class="ef-contact-avatar">${c.photo?`<img src="${c.photo}" alt="">`:'<i class="fa-solid fa-user-secret"></i>'}</div><div class="ef-contact-info"><h3>${esc(c.name)} </h3><p>Alias: ${esc(c.alias||'—')} · Phone: ${esc(c.phone||'—')} · Location: ${esc(c.location||'—')}</p><p>Affiliation: ${esc((c.affiliations||[]).map(a=>a.gang+' ('+a.position+')').join(', ')||c.gang||'—')} · Cases: ${esc(c.cases||'—')}</p><p>${esc(c.notes||'No notes')}</p><p>${[c.dob?'DOB: '+c.dob:'',c.physical?'Description: '+c.physical:'',c.vehicles?'Vehicles: '+c.vehicles:'',c.associates?'Associates: '+c.associates:''].filter(Boolean).map(esc).join(' · ')}</p><small>Added by ${esc(c.addedBy||'Unknown')} · Last contact ${esc(c.lastContact||'Not recorded')}</small></div><div class="ef-contact-actions"><button data-contactview="${esc(c.id)}">View Contact Card</button><button data-contactedit="${esc(c.id)}">Edit</button><button data-contactdelete="${esc(c.id)}">Delete</button></div></div>`).join(''):'<div class="db-card">No contacts found. Click + Add Contact to create one.</div>'};document.getElementById('contactSearch').oninput=draw;draw();content.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.contactedit)openContact(b.dataset.contactedit);if(b.dataset.contactdelete&&confirm('Delete this contact?')){contacts=contacts.filter(c=>c.id!==b.dataset.contactdelete);contactSave();draw()}}}
const itemsBtn=document.getElementById('addEntryBtn');
itemsBtn.addEventListener('click',e=>{if(currentSection==='contacts'){e.stopImmediatePropagation();openContact();return}if(currentSection!=='items')return;e.stopImmediatePropagation();openItemEditor()},true);
function openItemEditor(index=null){const old=(database.items||[])[index]||{};document.body.insertAdjacentHTML('beforeend',`<div id="itemOverlay" class="ef-overlay"><div class="ef-dialog ef-item-dialog"><div class="ef-dialog-head"><h2>${index===null?'Add Criminal Item':'Edit Criminal Item'}</h2><button id="itemClose">✕</button></div><form id="itemForm"><label>Picture / Emoji<input id="itemPicture" type="text" maxlength="12" placeholder="💊" value="${esc(old.picture||'')}"></label><label>Or upload an image<input id="itemImage" type="file" accept="image/png,image/jpeg,image/webp"></label><div id="itemImagePreview">${old.image?`<img src="${old.image}" width="80" alt="Item preview">`:''}</div><label>Name<input name="title" required value="${esc(old.title||'')}"></label><label>Description / What it is used for<textarea name="description" required rows="4">${esc(old.description||'')}</textarea></label><label>Who Added<input name="addedBy" required value="${esc(old.addedBy||'')}" placeholder="Detective name"></label><label>Linked Case Number (optional)<input name="caseNo" value="${esc(old.caseNo||'')}"></label><div class="ef-actions"><button type="button" id="itemCancel">Cancel</button><button class="blue" type="submit">Save Item</button></div></form></div></div>`);const overlay=document.getElementById('itemOverlay');let image=old.image||'';const close=()=>overlay.remove();document.getElementById('itemClose').onclick=close;document.getElementById('itemCancel').onclick=close;document.getElementById('itemImage').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.size>250000)return alert('Maximum image size 250 KB for local storage.');const reader=new FileReader();reader.onload=()=>{image=reader.result;document.getElementById('itemImagePreview').innerHTML=`<img src="${image}" width="80" alt="Item preview">`};reader.readAsDataURL(file)};document.getElementById('itemForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());const entry={id:old.id||('item-'+crypto.randomUUID()),title:d.title.trim(),description:d.description.trim(),addedBy:d.addedBy.trim(),caseNo:d.caseNo.trim(),picture:document.getElementById('itemPicture').value.trim(),image,updated:new Date().toISOString()};database.items??=[];const before=[...database.items];if(index===null)database.items.push(entry);else database.items[index]=entry;try{saveDb()}catch{database.items=before;return alert('Browser storage full.')}close();renderExtra('items')}}
renderExtra=function(section){if(section!=='items')return oldRenderExtra(section);document.getElementById('extraTitle').textContent='CRIMINAL ITEMS';itemsBtn.textContent='+ Add Criminal Item';const rows=database.items||[];const content=document.getElementById('extraContent');content.innerHTML=`<div class="ef-items-wrap ef-item-tiles"><div class="ef-items-tools"><input type="search" id="efItemSearch" placeholder="Search item name, description, detective or case..." aria-label="Search criminal items"><span id="efItemCount"></span></div><div id="efItemResults"></div></div>`;const search=document.getElementById('efItemSearch');const draw=()=>{const q=search.value.trim().toLowerCase();const matches=rows.map((r,i)=>({r,i})).filter(({r})=>!q||[r.title,r.description,r.addedBy,r.caseNo].join(' ').toLowerCase().includes(q));document.getElementById('efItemCount').textContent=matches.length+' item'+(matches.length===1?'':'s');document.getElementById('efItemResults').innerHTML=matches.length?matches.map(({r,i})=>`<article class="ef-criminal-tile"><div class="ef-criminal-main"><div class="ef-criminal-photo">${r.image?`<img src="${esc(r.image)}" alt="${esc(r.title||'Criminal item')}">`:`<i class="fa-solid fa-box-archive" aria-hidden="true"></i>`}</div><div class="ef-criminal-name"><strong>${esc(r.title||'Unnamed item')}</strong><small>Criminal Item</small></div><div class="ef-criminal-field"><span>DESCRIPTION</span><p>${esc(r.description||'No description')}</p></div><div class="ef-criminal-field"><span>ADDED BY</span><p>${esc(r.addedBy||'Unknown')}</p></div><div class="ef-criminal-field"><span>LINKED CASE</span><p>${esc(r.caseNo||'None')}</p></div><div class="ef-criminal-buttons"><button type="button" data-itemedit="${i}">Edit</button><button type="button" class="ef-criminal-delete" data-itemdelete="${i}">Delete</button></div></div></article>`).join(''):'<div class="ef-criminal-empty">No criminal items found.</div>'};search.oninput=draw;draw();content.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.itemedit!==undefined)openItemEditor(+b.dataset.itemedit);if(b.dataset.itemdelete!==undefined&&confirm('Delete this criminal item?')){database.items.splice(+b.dataset.itemdelete,1);saveDb();renderExtra('items')}}};
showSection=function(section){oldShowSection(section);const action=document.getElementById('addEntryBtn');if(section==='cases'||section==='map'||section==='settings'||section==='search'){action.style.display='none'}else if(section==='items'){renderExtra('items');action.textContent='+ Add Criminal Item';action.style.display=''}else if(section==='contacts'){renderContacts();action.textContent='+ Add Contact';action.style.display=''}else{action.textContent=section==='gangs'?'+ Add Gang':section==='vehicles'?'+ Add Vehicle':section==='history'?'+ Add History Record':'+ Add Record';action.style.display=''}if(section==='cases')renderRecords()};
renderRecords();
})();

