(()=>{
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
 const KEY='eflspddb_location_profiles_v1',FILES='eflspddb_investigation_files_v1';
 const read=(k,def)=>{try{return JSON.parse(localStorage.getItem(k))||def}catch{return def}};
 const profiles=()=>read(KEY,{}),files=()=>read(FILES,[]);
 const getPin=id=>cases.find(p=>p.kind==='general'&&String(p.id)===String(id));
 const linked=(pin)=>files().filter(f=>Array.isArray(f.linked)&&f.linked.map(String).includes(String(pin.id)));
 const close=()=>{document.getElementById('efLocationProfile')?.remove();document.querySelector('.rightpanel > .panel-inner')?.classList.remove('ef-panel-hidden');};
 async function readPhotos(photos){const results=[];for(const photo of photos){if(photo.size>350000||!['image/png','image/jpeg','image/webp'].includes(photo.type))throw Error('Choose PNG, JPG or WebP photographs under 350 KB each.');results.push(await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Unable to read photo'));reader.readAsDataURL(photo)}))}return results}

 function openCase(id){close();showSection('cases');const button=[...document.querySelectorAll('[data-fileopen]')].find(el=>el.getAttribute('data-fileopen')===String(id));if(button)button.click();}
 function openGang(index){close();showSection('gangs');const b=[...document.querySelectorAll('[data-gang-open]')].find(el=>el.getAttribute('data-gang-open')===String(index));if(b)b.click();}
 function showProfile(id,edit=false){
  const pin=getPin(id);if(!pin)return;const saved=profiles()[id]||{},all=files(),assigned=linked(pin);
  const gi=pin.linkedGang!==undefined&&pin.linkedGang!==''?Number(pin.linkedGang):-1;
  const gang=database.gangs?.[gi]||((pin.markerCategory==='Gang / Territory')?(database.gangs||[]).find(g=>String(g.title||'').toLowerCase()===String(pin.caseNo||'').toLowerCase()):null);
  const members=Array.isArray(gang?.members)?gang.members:[];
  const rosterHtml=members.map(m=>`<div class="ef-roster-member"><strong>${esc(m.name||'Unnamed Member')}</strong><span>${esc(m.position||m.role||'Member')}</span><small>${esc(m.alias?'Alias: '+m.alias:'')}${m.status?' · '+esc(m.status):''}</small></div>`).join('')||'<p>No members added to this gang roster yet.</p>';
  close();const overlay=document.createElement('div');overlay.id='efLocationProfile';overlay.className='ef-overlay ef-docked-location';
  const notes=esc(saved.notes||''),activity=esc(saved.activity||''),people=esc(saved.people||''),vehicles=esc(saved.vehicles||'');
  const assignedIcon=typeof markerIcon==='function'?markerIcon(pin).options.html:'';
  const gallery=[...new Set([saved.image,...(Array.isArray(saved.gallery)?saved.gallery:[])].filter(v=>typeof v==='string'&&/^data:image\/(?:png|jpeg|webp);base64,/.test(v)))];
  const image=gallery.length?`<img src="${esc(gallery[0])}" alt="Location photograph" class="ef-location-photo" data-gallery-open="0">`:'';
  const thumbnails=gallery.map((src,i)=>`<div class="ef-gallery-tile"><button type="button" data-gallery-open="${i}" title="View photo ${i+1}"><img src="${esc(src)}" alt="Location photo ${i+1}"></button><button type="button" class="ef-gallery-remove" data-gallery-remove="${i}" title="Remove photo">×</button><button type="button" data-gallery-main="${i}" title="Set as main photo">★</button></div>`).join('');
  const caseCards=assigned.map(f=>`<div class="ef-loc-case-linked"><button type="button" class="ef-loc-case-card" data-open-case="${esc(f.id)}"><strong>${esc(f.number||'Case')}</strong><span>${esc(f.title||'Untitled')}</span><small>${esc(f.status||'')}</small></button><button type="button" class="ef-loc-unlink" data-unlink-case="${esc(f.id)}" aria-label="Remove case link">Remove Link</button></div>`).join('');
  const category=pin.markerCategory||pin.category||'Map Location';
  const postal=String(pin.location||'Not specified');
  const status=String(pin.status||'Active');
  const hero=image||`<div class="ef-profile-no-photo"><i class="fa-solid fa-camera"></i><span>No location photo yet</span></div>`;
  const relatedFields=[['Division / Operator',saved.division],['Zone / District',saved.zone],['Phone / Contact',saved.phone],['Operating Hours',saved.hours]].filter(x=>x[1]);
  overlay.innerHTML=`<div class="ef-dialog ef-location-dialog ef-premium-location" role="dialog" aria-label="${esc(category)} profile">
   <div class="ef-profile-top"><div class="ef-profile-avatar">${image||assignedIcon||'<i class="fa-solid fa-location-dot"></i>'}</div><div class="ef-profile-headline"><h2>${esc(pin.caseNo||'Marked Location')}</h2><span>${esc(category)}</span><p>Postal: ${esc(postal)}</p></div><button class="ef-profile-x" data-loc-close aria-label="Close">✕</button></div>
   <div class="ef-profile-toolbar"><button data-loc-map class="blue"><i class="fa-solid fa-map"></i> Open in Map</button><button data-loc-share><i class="fa-solid fa-share-nodes"></i> Share</button><span class="ef-profile-flex"></span><button data-loc-edit class="ef-edit-gold"><i class="fa-solid fa-pen"></i> Edit</button><button data-loc-delete class="ef-delete-red"><i class="fa-solid fa-trash"></i> Delete</button></div>
   <div class="ef-loc-tabs ef-profile-tabs"><button type="button" data-loc-tab="overview" class="selected">Overview</button><button type="button" data-loc-tab="evidence">Media (${gallery.length})</button><button type="button" data-loc-tab="cases">Linked Cases (${assigned.length})</button><button type="button" data-loc-tab="connections">Notes</button>${gang||category==='Gang / Territory'?`<button type="button" data-loc-tab="roster">Roster (${members.length})</button>`:''}<button type="button" data-loc-tab="history">History</button></div>
   <section data-loc-panel="overview"><div class="ef-profile-card"><div class="ef-profile-overview"><dl><dt>Name</dt><dd>${esc(pin.caseNo||'Marked Location')}</dd><dt>Type</dt><dd>${esc(category)}</dd><dt>Postal</dt><dd>${esc(postal)}</dd><dt>Status</dt><dd><span class="ef-status-chip">${esc(status)}</span></dd><dt>Linked Cases</dt><dd>${assigned.length}</dd></dl><div class="ef-profile-hero">${hero}</div></div><div class="ef-profile-description"><small>Description</small><p>${notes||'No location description added yet.'}</p></div></div>
   <div class="ef-profile-card"><h3><i class="fa-solid fa-building-columns"></i> Associated Information</h3><div class="ef-profile-fields">${relatedFields.map(([k,v])=>`<div><small>${esc(k)}</small><span>${esc(v)}</span></div>`).join('')||'<p>No additional location information recorded yet.</p>'}</div>${activity?`<p class="ef-profile-activity"><strong>Known Activity</strong><span>${activity}</span></p>`:''}</div>
   <div class="ef-profile-card"><h3><i class="fa-solid fa-file-lines"></i> Linked Cases (${assigned.length}) <button class="blue ef-inline-action" data-loc-tab="cases">+ Link Case</button></h3><div class="ef-loc-case-grid">${caseCards||'<p>No linked cases yet.</p>'}</div></div></section>
   <section data-loc-panel="evidence" hidden><div class="ef-profile-card"><h3><i class="fa-solid fa-images"></i> Location Media</h3><div class="ef-location-gallery">${thumbnails||'<p>No photos added yet.</p>'}</div><label class="ef-gallery-upload">+ Add Location Photos<input type="file" data-gallery-files accept="image/png,image/jpeg,image/webp" multiple></label><p class="ef-hint">Maximum 350 KB per photo. Photos are stored in this browser.</p></div></section>
   <section data-loc-panel="roster" hidden><div class="ef-profile-card"><h3><i class="fa-solid fa-users"></i> Gang Roster (${members.length})</h3><div class="ef-roster-list">${rosterHtml}</div><p class="ef-hint">Roster members are managed from the Gangs directory.</p></div></section>
   <section data-loc-panel="cases" hidden><div class="ef-profile-card"><h3>Linked Investigations</h3><div class="ef-loc-case-grid">${caseCards||'<p>No investigations linked to this pin.</p>'}</div><h3>Link More Cases</h3><div class="ef-loc-checklist">${all.filter(f=>!assigned.some(a=>String(a.id)===String(f.id))).map(f=>`<label><input type="checkbox" data-link-case="${esc(f.id)}"> <span>${esc(f.number||'Case')} — ${esc(f.title||'Untitled')}</span></label>`).join('')||'<p>All available investigations are already linked, or no cases exist.</p>'}</div><button type="button" class="blue" data-save-links>Save Case Links</button></div></section>
   <section data-loc-panel="connections" hidden><div class="ef-profile-card"><h3>Intelligence Notes</h3><p>${notes||'No notes recorded yet.'}</p><h3>Known Activity</h3><p>${activity||'No activity recorded yet.'}</p><h3>Known Individuals</h3><p>${people||'None recorded.'}</p><h3>Associated Vehicles</h3><p>${vehicles||'None recorded.'}</p>${gang?`<button data-open-gang="${gi}">View ${esc(gang.title)} Gang Profile</button>`:''}</div></section>
   <section data-loc-panel="history" hidden><div class="ef-profile-card"><h3>Location History</h3><p>${pin.updated?'Last updated: '+esc(new Date(pin.updated).toLocaleString()):'No recorded updates yet.'}</p></div></section>
   <div class="ef-loc-editor" ${edit?'':'hidden'}><h3>Edit Location</h3><p class="ef-hint">Edit location intelligence, photograph, and pin settings together.</p><button type="button" data-loc-appearance class="ef-loc-secondary">Edit Pin Appearance / Position</button><label class="ef-loc-lock"><input type="checkbox" data-loc-lock ${pin.locked?'checked':''}> 🔒 Lock this marker against accidental repositioning</label><label>Location Description<textarea data-loc-field="notes" rows="3">${notes}</textarea></label><label>Known Activity<textarea data-loc-field="activity" rows="3">${activity}</textarea></label><label>Known Individuals / Contacts<textarea data-loc-field="people" rows="2">${people}</textarea></label><label>Associated Vehicles<textarea data-loc-field="vehicles" rows="2">${vehicles}</textarea></label><div class="ef-profile-edit-fields"><label>Division / Operator<input data-loc-field="division" value="${esc(saved.division||'')}"></label><label>Zone / District<input data-loc-field="zone" value="${esc(saved.zone||'')}"></label><label>Phone / Contact<input data-loc-field="phone" value="${esc(saved.phone||'')}"></label><label>Operating Hours<input data-loc-field="hours" value="${esc(saved.hours||'')}"></label></div><label>Add Location Photos<input type="file" data-loc-image accept="image/png,image/jpeg,image/webp" multiple></label><button type="button" class="blue" data-loc-save>Save Location File</button></div>
  </div>`;
  document.querySelector('.rightpanel > .panel-inner')?.classList.add('ef-panel-hidden');document.querySelector('.rightpanel').appendChild(overlay);
  overlay.addEventListener('change',async event=>{if(!event.target.matches('[data-gallery-files]'))return;try{const added=await readPhotos([...event.target.files]);const all=[...gallery,...added];const next=profiles();next[id]={...saved,image:all[0]||'',gallery:all};localStorage.setItem(KEY,JSON.stringify(next));showProfile(id)}catch(err){alert(err.message||'Could not save photographs. Browser storage may be full.')}});

  overlay.addEventListener('pointerdown',e=>{if(e.target===overlay)close()});
  overlay.addEventListener('click',e=>{
   const b=e.target.closest('button');if(!b)return;
   if(b.hasAttribute('data-gallery-open')){const src=gallery[Number(b.dataset.galleryOpen)];if(src){const viewer=document.createElement('div');viewer.className='ef-gallery-viewer';viewer.innerHTML=`<button type="button" aria-label="Close photo viewer">×</button><img src="${esc(src)}" alt="Enlarged location photograph">`;document.body.append(viewer);viewer.addEventListener('click',()=>viewer.remove())}return}
   if(b.hasAttribute('data-gallery-main')||b.hasAttribute('data-gallery-remove')){const index=Number(b.dataset.galleryMain??b.dataset.galleryRemove);const updated=[...gallery];if(b.hasAttribute('data-gallery-main')){updated.unshift(...updated.splice(index,1))}else{if(!confirm('Remove this photograph?'))return;updated.splice(index,1)}const next=profiles();next[id]={...saved,image:updated[0]||'',gallery:updated};try{localStorage.setItem(KEY,JSON.stringify(next));showProfile(id)}catch{alert('Unable to save photo changes.')}return}
   if(b.hasAttribute('data-loc-close')){close();return}
   if(b.hasAttribute('data-loc-map')){map.setView([pin.lat,pin.lng],Math.max(map.getZoom(),2),{animate:true});return}
   if(b.hasAttribute('data-loc-share')){const message=`${pin.caseNo||'Location'} — ${category}, postal ${postal}`;if(navigator.clipboard?.writeText){navigator.clipboard.writeText(message).then(()=>alert('Location details copied.')).catch(()=>prompt('Copy location details:',message))}else prompt('Copy location details:',message);return}
   if(b.hasAttribute('data-loc-delete')){
    // Use the authenticated shared deletion workflow; never remove a pin only locally.
    // Closing the profile after a successful deletion avoids a stale panel.
    if(b.disabled)return;
    if(typeof window.EFDBDeletePin!=='function'){alert('Pin deletion is unavailable. Please refresh and try again.');return;}
    b.disabled=true;
    Promise.resolve(window.EFDBDeletePin(pin)).then(()=>{
      if(!cases.some(c=>String(c.id)===String(id)))close();
    }).catch(err=>{console.error('Location deletion failed',err);}).finally(()=>{if(b.isConnected)b.disabled=false;});
    return;
   }
   if(b.hasAttribute('data-loc-tab')){const tab=b.dataset.locTab;overlay.querySelectorAll('[data-loc-tab]').forEach(t=>t.classList.toggle('selected',t.dataset.locTab===tab));overlay.querySelectorAll('[data-loc-panel]').forEach(t=>t.hidden=t.dataset.locPanel!==tab);return}
   if(b.hasAttribute('data-open-case')){openCase(b.dataset.openCase);return}
   if(b.hasAttribute('data-open-gang')){openGang(b.dataset.openGang);return}
   if(b.hasAttribute('data-loc-appearance')){close();openModal(pin,'general');return}
   if(b.hasAttribute('data-loc-edit')){const ed=overlay.querySelector('.ef-loc-editor');ed.hidden=!ed.hidden;b.innerHTML=ed.hidden?'<i class="fa-solid fa-pen"></i> Edit':'Hide Editor';if(!ed.hidden)ed.scrollIntoView({block:'nearest',behavior:'smooth'});return}
   if(b.hasAttribute('data-unlink-case')){const target=String(b.dataset.unlinkCase);const list=files();const match=list.find(f=>String(f.id)===target);if(match){match.linked=(Array.isArray(match.linked)?match.linked:[]).filter(x=>String(x)!==String(id));try{localStorage.setItem(FILES,JSON.stringify(list));showProfile(id)}catch{alert('Unable to remove case link.')}}return}
   if(b.hasAttribute('data-save-links')){const ids=new Set([...overlay.querySelectorAll('[data-link-case]:checked')].map(el=>el.dataset.linkCase));const list=files();list.forEach(f=>{f.linked=Array.isArray(f.linked)?f.linked:[];if(ids.has(String(f.id))&&!f.linked.some(x=>String(x)===String(id)))f.linked.push(id)});try{localStorage.setItem(FILES,JSON.stringify(list));showProfile(id);overlay.remove()}catch{alert('Unable to save case links. Check browser storage space.')}return}
   if(b.hasAttribute('data-loc-save')){const locked=!!overlay.querySelector('[data-loc-lock]')?.checked;if(pin.locked!==locked){pin.locked=locked;pin.updated=new Date().toISOString();saveCases();render();}const record={...saved};overlay.querySelectorAll('[data-loc-field]').forEach(t=>record[t.dataset.locField]=t.value);const photos=[...overlay.querySelector('[data-loc-image]').files];const commit=async()=>{try{const added=await readPhotos(photos);const all=[...gallery,...added];record.image=all[0]||'';record.gallery=all;const next=profiles();next[id]=record;localStorage.setItem(KEY,JSON.stringify(next));showProfile(id)}catch(err){alert(err.message||'Could not save photographs. Browser storage may be full.')}};commit();return}
  });
 }
 window.openLocationIntelligenceProfile=showProfile;
 const priorRender=render;
 function refresh(){if(typeof markerLayer==='undefined')return;markerLayer.eachLayer(marker=>{const pos=marker.getLatLng();const pin=cases.find(c=>c.kind==='general'&&c.lat===pos.lat&&c.lng===pos.lng);if(!pin)return;const gangIndex=pin.linkedGang!==undefined&&pin.linkedGang!==''?Number(pin.linkedGang):-1;const gang=database.gangs?.[gangIndex];const count=linked(pin).length;const html=`<div class="gang-map-popup ef-location-popup"><strong>${esc(pin.caseNo||'Marked Location')}</strong><small>${esc(pin.location||'')}</small><p>${count} linked investigation${count===1?'':'s'}</p><span>Click pin to open location intelligence file</span></div>`;marker.unbindTooltip();marker.bindTooltip(html,{direction:'top',offset:[0,-24],opacity:1,className:'case-map-tooltip gang-map-tooltip'});marker.unbindPopup();marker.off('click');marker.on('click',e=>{if(e.originalEvent)L.DomEvent.stop(e.originalEvent);marker.closeTooltip();showProfile(pin.id)});});}
 render=function(){priorRender();refresh()};refresh();
})();

;

