/* ===== SOURCE: high-command.js ===== */
/* High Command directory; browser-local until secure Supabase sign-in is deployed. */
(()=>{'use strict';
const KEY='eflspddb_high_command_v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=()=>{try{let x=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(x)?x:[]}catch{return []}};
const write=a=>localStorage.setItem(KEY,JSON.stringify(a));
const form=(entry,index)=>{
 const overlay=document.createElement('div');overlay.className='ef-hc-overlay';overlay.innerHTML=`<form class="ef-hc-form"><div class="ef-hc-formtop"><h2>${index<0?'Add High Command':'Edit High Command'}</h2><button type="button" data-close>×</button></div><label>Name<input name="name" maxlength="90" required value="${esc(entry.name)}"></label><label>Rank<input name="rank" maxlength="90" value="${esc(entry.rank)}"></label><label>Callsign<input name="callsign" maxlength="40" value="${esc(entry.callsign)}"></label><label>Badge<input name="badge" maxlength="40" value="${esc(entry.badge)}"></label><label>Notes<textarea name="notes" rows="3">${esc(entry.notes)}</textarea></label><div class="ef-hc-actions"><button type="button" data-close>Cancel</button><button class="blue" type="submit">Save Member</button></div></form>`;
 document.body.append(overlay);overlay.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>overlay.remove());overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.remove()});overlay.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const item={name:String(f.get('name')).trim(),rank:String(f.get('rank')).trim(),callsign:String(f.get('callsign')).trim(),badge:String(f.get('badge')).trim(),notes:String(f.get('notes')).trim()};if(!item.name)return;let a=read();if(index<0)a.push(item);else a[index]=item;write(a);overlay.remove();show()};
};
function show(){const view=$('#extraView'),content=$('#extraContent');if(!view||!content)return;
$('#mapView')?.classList.add('hidden');$('#recordsView')?.classList.add('hidden');view.classList.remove('hidden');$('#extraTitle').textContent='HIGH COMMAND';const add=$('#addEntryBtn');if(add)add.style.display='none';
const items=read();content.innerHTML=`<div class="db-card ef-hc-page"><div class="ef-heading-row"><div><h3>HIGH COMMAND ROSTER</h3><p>Command personnel and departmental positions.</p></div><button class="blue" id="efHCAdd"><i class="fa-solid fa-plus"></i> Add Member</button></div><p class="ef-hc-warning">This roster is saved in this browser only. Shared editing will be enabled after secure Supabase authentication is connected.</p><div class="ef-hc-list">${items.length?items.map((m,i)=>`<div class="ef-hc-member"><div class="ef-hc-avatar"><i class="fa-solid fa-shield-halved"></i></div><div class="ef-hc-details"><strong>${esc(m.name)}</strong><span>${esc(m.rank||'Rank not set')} · ${esc(m.callsign||'No callsign')}</span><small>Badge: ${esc(m.badge||'—')}</small>${m.notes?`<p>${esc(m.notes)}</p>`:''}</div><div class="ef-hc-controls"><button data-edit="${i}">Edit</button><button data-delete="${i}">Remove</button></div></div>`).join(''):'<p>No High Command members yet. Use Add Member to create the first profile.</p>'}</div></div>`;
$('#efHCAdd').onclick=()=>form({},-1);content.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.edit);form(read()[i],i)});content.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Remove this High Command member?'))return;const a=read();a.splice(Number(b.dataset.delete),1);write(a);show()});
}
function init(){const btn=$('[data-section="high-command"]');if(!btn)return;btn.addEventListener('click',e=>{e.stopImmediatePropagation();document.querySelectorAll('.ef-primary-navigation button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');show()},true);document.querySelectorAll('.ef-primary-navigation button:not([data-section="high-command"])').forEach(b=>b.addEventListener('click',()=>{$('#addEntryBtn')?.style.removeProperty('display')},true));}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();

;

