/* ===== SOURCE: auth-admin.js ===== */
(()=>{'use strict';
const titles={owner:'Office of Operations',high_command:'High Command',admin:'Supervisory Detective',director:'Director',deputy_director:'Deputy Director',supervisory_detective:'Supervisory Detective',detective:'Detective',junior_detective:'Junior Detective',probationary_detective:'Probationary Detective'};
window.EFDBRoleTitle=r=>titles[r]||r;
const ranks=['high_command','director','deputy_director','supervisory_detective','detective','junior_detective','probationary_detective'];
const permissionNames={view_investigations:'View investigations',create_investigations:'Create investigations',edit_investigations:'Edit investigations',delete_investigations:'Delete investigations',manage_gangs_contacts:'Manage gangs & contacts',upload_evidence:'Upload evidence',create_accounts:'Create detective accounts',reset_passcodes:'Reset passcodes',manage_roles:'Manage user roles',view_storage_usage:'View Storage & Usage'};
const css=document.createElement('style');css.textContent=`.ef4-modal{position:fixed;inset:5vh 7vw;z-index:9500;background:#111f36;border:1px solid #49668e;color:#e8f2ff;border-radius:14px;box-shadow:0 20px 80px #000b;padding:22px;overflow:auto;font:14px Arial;resize:both;min-width:320px;min-height:240px}.ef4-modal button{background:#2e66ad;color:white;border:1px solid #6484a8;padding:8px 12px;border-radius:6px;cursor:pointer;margin:3px}.ef4-modal input,.ef4-modal select,.ef4-modal textarea{background:#0b192c;color:white;border:1px solid #536c8d;border-radius:5px;padding:9px;margin:4px;max-width:100%}.ef4-modal table{width:100%;border-collapse:collapse}.ef4-modal td,.ef4-modal th{padding:8px;border-bottom:1px solid #394960;text-align:left}.ef4-modal .ef4-danger{background:#8d2c3a}.ef4-modal .ef4-secret{font-size:23px;letter-spacing:2px;padding:12px;background:#183955}.ef4-modal .ef4-tabs{display:flex;gap:8px;margin:12px 0}.ef4-modal .ef4-msg{color:#f4cf84;margin:12px 0;white-space:pre-wrap}.ef4-modal .ef4-photo{max-width:140px;max-height:140px;object-fit:cover;border-radius:9px}.ef4-modal .ef4-flex{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.ef4-modal label{display:inline-flex;flex-direction:column;margin:4px}.ef4-modal .ef4-check{accent-color:#61a9ff;width:17px;height:17px}`;document.head.append(css);
function el(tag,text,cls){const x=document.createElement(tag);if(text!=null)x.textContent=text;if(cls)x.className=cls;return x;}
function btn(text,fn,cls){const b=el('button',text,cls);b.type='button';b.onclick=fn;return b;}
function field(label,value='',type='text'){const w=el('label');w.append(el('span',label));const i=document.createElement(type==='textarea'?'textarea':'input');if(type!=='textarea')i.type=type;i.value=value||'';w.append(i);return [w,i];}
function modal(title,child=false){if(!child)document.querySelectorAll('.ef4-modal').forEach(x=>x.remove());const box=el('section',null,'ef4-modal'+(child?' ef5-child':' ef5-main'));box.setAttribute('role','dialog');box.setAttribute('aria-label',title);const top=el('div',null,'ef4-flex ef5-heading');top.append(el('h2',title),btn('✕',()=>box.remove(),'ef5-close'));box.append(top);document.body.append(box);return box;}
function confirmAction(title,description,actionLabel,danger=false){return new Promise(resolve=>{const box=modal(title,true);box.append(el('p',description,'ef5-description'));const actions=el('div',null,'ef5-actions');actions.append(btn('Cancel',()=>{box.remove();resolve(false);},'ef5-cancel'),btn(actionLabel,()=>{box.remove();resolve(true);},danger?'ef4-danger':''));box.append(actions);});}
function nameDialog(account){return new Promise(resolve=>{const box=modal('Change Display Name',true);box.append(el('p','Update the name shown on your detective account.','ef5-description'));const [wrap,input]=field('Display name',account.display_name);input.maxLength=100;input.required=true;box.append(wrap);const actions=el('div',null,'ef5-actions');const finish=value=>{box.remove();resolve(value);};actions.append(btn('Cancel',()=>finish(null),'ef5-cancel'),btn('Save Changes',()=>{const value=input.value.trim();if(!value){message(box,'Enter a display name.');input.focus();return;}finish(value);}));box.append(actions);input.focus();input.select();input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();actions.lastChild.click();}});});}
function deleteDialog(account){return new Promise(resolve=>{const box=modal('Permanently Delete Account',true);box.append(el('p',`This permanently removes the login account for ${account.display_name}. This cannot be undone. Existing cases are not deleted.`,'ef5-description'));const [wrap,input]=field('Type the exact detective name to confirm');input.autocomplete='off';input.spellcheck=false;box.append(wrap);const warning=el('p','This action cannot be reversed.','ef5-warning');box.append(warning);const actions=el('div',null,'ef5-actions');const cancel=btn('Cancel',()=>{box.remove();resolve(null);},'ef5-cancel');const remove=btn('Delete Permanently',()=>{if(input.value!==account.display_name){message(box,'The name must match exactly: '+account.display_name);return;}box.remove();resolve(input.value);},'ef4-danger');remove.disabled=true;input.addEventListener('input',()=>{remove.disabled=input.value!==account.display_name;});actions.append(cancel,remove);box.append(actions);input.focus();input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!remove.disabled){e.preventDefault();remove.click();}});});}
function profileRow(label,value){const wrap=el('div',null,'ef5-info');wrap.append(el('span',label,'ef5-label'),el('strong',String(value||'Not provided')));return wrap;}

function message(box,text){let m=box.querySelector('.ef4-msg');if(!m){m=el('div',null,'ef4-msg');box.append(m);}m.textContent=text;return m;}
function revealCode(box,code,who){const pop=modal('Temporary Passcode Generated',true);pop.append(el('p',`${who}'s temporary passcode has been generated. Copy it now; it will not be displayed again.`,'ef5-description'));const secret=el('div','•••• •••• ••••','ef5-code');pop.append(secret);const actions=el('div',null,'ef5-actions');let shown=false;actions.append(btn('Show Code',()=>{shown=!shown;secret.textContent=shown?code:'•••• •••• ••••';}));actions.append(btn('Copy Code',async()=>{try{await navigator.clipboard.writeText(code);message(pop,'Copied to clipboard.');}catch(e){message(pop,'Copy failed. Use Show Code to copy manually.');}}));pop.append(actions,el('p','The detective must change this code on their next login.','ef5-warning'));}
async function request(path,data){return window.EFDBAuth.request(path,data);}
async function showProfile(account){const box=modal('Detective Profile',true);try{const r=await request('/accounts',{action:'profile',id:account.id});if(!box.isConnected)return;const p=r.profile;const hero=el('div',null,'ef5-hero');const photo=el('div',null,'ef5-avatar');if(p.profile_photo_path&&/^https:\/\//i.test(p.profile_photo_path)){const im=document.createElement('img');im.src=p.profile_photo_path;im.alt='Detective photograph';im.referrerPolicy='no-referrer';im.onerror=()=>{photo.textContent='👤';};photo.append(im);}else photo.textContent='👤';const details=el('div');details.append(el('h3',p.name||p.display_name||account.display_name),el('div',titles[p.role]||p.role,'ef5-rank'),el('small','Los Santos Police Department'));hero.append(photo,details);box.append(hero);const info=el('div',null,'ef5-grid');info.append(profileRow('BADGE NUMBER',p.badge_number),profileRow('CALLSIGN',p.callsign),profileRow('PHONE NUMBER',p.phone_number));box.append(info);const notes=el('div',null,'ef5-notes');notes.append(el('span','PROFILE NOTES','ef5-label'),el('p',p.profile_notes||'No notes added.'));box.append(notes);if(window.EFDBAuth?.user?.role==='owner'||window.EFDBAuth?.user?.id===account.id){const actions=el('div',null,'ef5-actions');actions.append(btn('Edit Profile',()=>editProfile({...account,...p})));box.append(actions);}}catch(e){message(box,e.message);}}
async function editProfile(account){const box=modal('Edit Detective Profile',true);const fields={};for(const [key,label] of [['badge_number','Badge number'],['callsign','Callsign'],['phone_number','Phone number'],['profile_notes','Profile notes'],['profile_photo_path','Photo URL (HTTPS)']]){const [w,i]=field(label,account[key],key==='profile_notes'?'textarea':'text');fields[key]=i;box.append(w);}box.append(el('p','Direct photo uploads are not enabled yet. Use an HTTPS image URL.','ef5-description'));const actions=el('div',null,'ef5-actions');actions.append(btn('Cancel',()=>box.remove(),'ef5-cancel'),btn('Save Profile',async()=>{try{const data={action:'update_profile',id:account.id};for(const [k,i] of Object.entries(fields))data[k]=i.value.trim();await request('/accounts',data);message(box,'Profile saved.');}catch(e){message(box,e.message);}}));box.append(actions);}
async function openAdmin(){const api=window.EFDBAuth;if(!api?.loggedIn)return;const user=api.user;const box=modal('EFLSPDDB · Account Management');const tabs=el('div',null,'ef4-tabs'),area=el('div');box.append(tabs,area);const sections=[['Accounts',accountsTab]];if(['owner','high_command'].includes(user.role))sections.push(['Role Permissions',permissionsTab]);for(const [name,fn] of sections)tabs.append(btn(name,()=>{area.replaceChildren();fn(area,box);}));accountsTab(area,box);
async function accountsTab(area,box){const result=el('div',null,'ef4-msg');area.append(result);let data;try{data=await request('/accounts',{action:'list'});}catch(e){result.textContent=e.message;return;}
const form=document.createElement('form');form.className='ef4-flex';const [nw,name]=field('Personnel name');name.required=true;const [bw,badge]=field('Badge number');const [cw,callsign]=field('Callsign');const [pw,phone]=field('Phone number');const [uw,photo]=field('Photo URL (HTTPS)');const role=document.createElement('select');const current=['owner','high_command','director','deputy_director','supervisory_detective','admin','detective','junior_detective','probationary_detective'];const idx=current.indexOf(user.role);for(const r of ranks){if((r!=='high_command'||user.role==='owner')&&(['owner','high_command'].includes(user.role)||current.indexOf(r)>idx)){const o=document.createElement('option');o.value=r;o.textContent=titles[r];role.append(o);}}const [rw]=field('Role');rw.lastChild.replaceWith(role);const create=el('button','Create account');create.type='submit';form.append(nw,rw,bw,cw,pw,uw,create);area.append(form);
form.onsubmit=async e=>{e.preventDefault();create.disabled=true;try{const r=await request('/accounts',{action:'create',name:name.value.trim(),role:role.value,badge_number:badge.value,callsign:callsign.value,phone_number:phone.value,profile_notes:''});revealCode(box,r.account.code,name.value);window.EF8GSyncAccounts?.([{id:r.account.id,display_name:name.value.trim(),role:role.value,badge_number:badge.value,callsign:callsign.value,active:true}]);if(photo.value.trim())await request('/accounts',{action:'update_profile',id:r.account.id,profile_photo_path:photo.value.trim()});await accountsTabReload();}catch(err){result.textContent=err.message;}finally{create.disabled=false;}};
const table=el('table');area.append(table);async function accountsTabReload(){const r=await request('/accounts',{action:'list'});window.EF8GSyncAccounts?.(r.accounts);table.replaceChildren();const h=el('tr');for(const v of ['Detective','Rank','Status','Actions'])h.append(el('th',v));table.append(h);for(const a of r.accounts){const tr=el('tr');for(const v of [a.display_name,titles[a.role]||a.role,a.active?'Active':'Disabled'])tr.append(el('td',v));const actions=el('td');actions.append(btn('Contact Card',()=>showProfile(a)),btn('Edit Profile',()=>editProfile(a)));if(a.active&&a.role!=='owner'&&a.id!==user.id){actions.append(btn('Reset Code',async()=>{if(!await confirmAction('Reset Detective Passcode','Generate a new temporary passcode for '+a.display_name+'? All existing sessions will end.','Reset Passcode'))return;try{const r=await request('/accounts',{action:'reset_code',id:a.id});revealCode(box,r.code,a.display_name);}catch(e){result.textContent=e.message;}}));if(['owner','high_command'].includes(user.role))actions.append(btn('Disable',async()=>{if(!await confirmAction('Disable Detective Account','Disable '+a.display_name+'? This detective will no longer be able to sign in.','Disable Account',true))return;try{await request('/accounts',{action:'disable',id:a.id});await accountsTabReload();}catch(e){result.textContent=e.message;}},'ef4-danger'));}if(['owner','high_command'].includes(user.role)){
 if(a.id===user.id)actions.append(btn('Change Name',async()=>{const next=await nameDialog(a);if(next===null)return;try{await request('/accounts',{action:'update_identity',id:a.id,display_name:next.trim()});await accountsTabReload();message(box,'Name saved. Log out and back in to refresh the header.');}catch(e){result.textContent=e.message;}}));
 if(!a.active&&a.role!=='owner'){
  actions.append(btn('Reactivate',async()=>{if(!await confirmAction('Reactivate Detective','Reactivate '+a.display_name+' with a NEW temporary passcode?','Reactivate'))return;try{const r=await request('/accounts',{action:'reactivate',id:a.id});await accountsTabReload();revealCode(box,r.code,a.display_name);}catch(e){result.textContent=e.message;}}));
  actions.append(btn('Delete Permanently',async()=>{const name=await deleteDialog(a);if(name===null)return;try{await request('/accounts',{action:'delete',id:a.id,confirm_name:name});await accountsTabReload();}catch(e){result.textContent=e.message;}},'ef4-danger'));
 }
}tr.append(actions);table.append(tr);}}await accountsTabReload();}
async function permissionsTab(area,box){
 let r;try{r=await request('/permissions',{action:'list'});}catch(e){message(box,e.message);return;}
 const roles=['owner','high_command',...ranks.filter(x=>x!=='high_command')];
 const t=el('table'),head=el('tr');head.append(el('th','Permission'));
 for(const role of roles)head.append(el('th',titles[role]||role));t.append(head);
 const status=el('p','Changes save immediately. Office of Operations and High Command always have access.','ef5-description');
 for(const permission of r.available_permissions){
  const tr=el('tr');tr.append(el('td',permissionNames[permission]||permission));
  if(permission==='view_storage_usage')tr.className='ef5-storage-permission';
  for(const role of roles){
   const td=el('td'),input=document.createElement('input');input.type='checkbox';input.className='ef4-check';
   const permanent=role==='owner'||role==='high_command';
   input.checked=permanent||r.permissions.some(x=>x.role===role&&x.permission===permission&&x.allowed===true);
   input.disabled=permanent;input.title=permanent?'Always enabled for this role':'Toggle '+(permissionNames[permission]||permission)+' for '+(titles[role]||role);
   if(!permanent)input.onchange=async()=>{
    const wanted=input.checked;input.disabled=true;status.textContent='Saving '+(permissionNames[permission]||permission)+' for '+(titles[role]||role)+'…';
    try{await request('/permissions',{action:'set',role,permission,allowed:wanted});status.textContent='Saved: '+(titles[role]||role)+' — '+(permissionNames[permission]||permission)+' '+(wanted?'enabled':'disabled')+'.';}
    catch(e){input.checked=!wanted;status.textContent='Could not save permission: '+e.message;message(box,e.message);}
    finally{input.disabled=false;}
   };
   td.append(input);tr.append(td);
  }t.append(tr);
 }
 area.append(status,t);
}
}
window.EFDBOpenAdmin=openAdmin;
window.addEventListener('efdb-change-required',()=>{const box=modal('Change Temporary Passcode',true);const note=el('p','Your temporary passcode must be replaced before you can access the database.');const [oldw,old]=field('Temporary code (6 or legacy 12 digits)','','password');const [neww,neo]=field('New 6-digit code','','password');const [confw,confirmCode]=field('Confirm new code','','password');box.append(note,oldw,neww,confw);box.querySelector('.ef5-close')?.remove();box.append(btn('Change Passcode',async()=>{if(!/^\d{6}$/.test(neo.value)||neo.value!==confirmCode.value){message(box,'New codes must be 6 digits and match.');return;}try{await request('/change-code',{current_code:old.value,code:neo.value});window.EFDBAuth.logout();box.remove();}catch(e){message(box,e.message);}}));});
window.addEventListener('efdb-auth-login',()=>{const u=window.EFDBAuth.user;if(!u)return;const bar=document.getElementById('efAuthBar');if(bar){bar.style.display='none';}const name=document.getElementById('efHeaderUserRole');if(name)name.textContent=titles[u.role]||u.role;});
window.addEventListener('efdb-auth-logout',()=>document.querySelector('.ef4-modal')?.remove());
})();
