/* ===== SOURCE: profile-popups.js ===== */
(()=>{'use strict';
const css=document.createElement('style');css.textContent=`
.ef-intel-dialog,.ef-dialog,.ef-admin,.ef-popup-card,.ef-photo-dialog{resize:both!important;overflow:auto!important;min-width:min(330px,92vw);min-height:230px;max-width:98vw;max-height:96vh}
.ef-intel-dialog{height:min(750px,90vh)}.ef-intel-avatar{cursor:zoom-in;flex-shrink:0}.ef-intel-avatar img{width:100%;height:100%;border-radius:50%;object-fit:cover}
.ef-popup-card,.ef-photo-dialog{background:#14223d;color:#e5efff;border:1px solid #54749d;border-radius:12px;padding:22px;width:min(660px,92vw);max-height:90vh;box-shadow:0 20px 70px #000b}
.ef-popup-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.ef-popup-head button{background:#25466e;border:1px solid #5478a7;color:#fff;border-radius:6px;padding:7px 12px;cursor:pointer}.ef-popup-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:18px 0}.ef-popup-grid div{background:#1b3151;padding:12px;border-radius:7px;overflow-wrap:anywhere}.ef-popup-grid small{display:block;color:#9bbce5;margin-bottom:6px}.ef-photo-dialog img{display:block;max-width:100%;max-height:70vh;object-fit:contain;margin:16px auto}.ef-intel-person .ef-intel-avatar{border:0;padding:0}
`;document.head.appendChild(css);
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function data(b){let [gi,mi]=b.split(':').map(Number);let g=window.database?.gangs?.[gi]||null;return {g,m:g?.members?.[mi]};}
function overlay(inner,klass){let o=document.createElement('div');o.className='ef-overlay';o.style.zIndex='200005';o.innerHTML=`<div class="${klass}" role="dialog" aria-modal="true">${inner}</div>`;document.body.append(o);o.addEventListener('pointerdown',e=>{if(e.target===o)o.remove()});o.querySelector('[data-popup-close]')?.addEventListener('click',()=>o.remove());const escKey=e=>{if(e.key==='Escape'){o.remove();document.removeEventListener('keydown',escKey)}};document.addEventListener('keydown',escKey);return o;}
document.addEventListener('click',e=>{const avatar=e.target.closest('.ef-intel-person .ef-intel-avatar');if(!avatar)return;const row=avatar.closest('.ef-intel-person');const key=row?.querySelector('[data-gang-contact]')?.dataset.gangContact;if(!key)return;e.preventDefault();e.stopPropagation();const {m}=data(key);if(!m)return;const photo=m.photo&&/^data:image\/(png|jpeg|webp);base64,/.test(m.photo)?m.photo:'';overlay(`<div class="ef-popup-head"><h2>${esc(m.name)} — Photograph</h2><button data-popup-close>Close ✕</button></div>${photo?`<img src="${photo}" alt="${esc(m.name)}">`:'<p>No photograph uploaded for this member.</p>'}`,'ef-photo-dialog');},true);

})();
;

