/* ===== SOURCE: contact-card-fix.js ===== */
(()=>{'use strict';
const style=document.createElement('style');style.textContent=`#contactEditor{z-index:200030!important}#contactEditor .ef-dialog{resize:both;overflow:auto;max-width:96vw;max-height:94vh}.ef-contact-actions button{position:relative;z-index:2;pointer-events:auto}.ef-contact-card .ef-contact-avatar{cursor:zoom-in}.ef-contact-profile-view{position:fixed;inset:0;z-index:200020;background:#000c;display:flex;align-items:center;justify-content:center;padding:18px}.ef-contact-profile-box{width:min(730px,96vw);max-height:92vh;min-height:280px;resize:both;overflow:auto;border-radius:12px;background:#14223d;border:1px solid #54749d;color:#e5efff;padding:22px;box-shadow:0 20px 80px #000b}.ef-contact-profile-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.ef-contact-profile-head button,.ef-contact-profile-actions button{background:#24517f;color:white;border:1px solid #557ca8;border-radius:6px;padding:9px 14px;cursor:pointer}.ef-contact-profile-photo{max-width:160px;max-height:160px;object-fit:cover;border-radius:10px;cursor:zoom-in}.ef-contact-profile-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:15px 0}.ef-contact-profile-grid>div{background:#1b3151;padding:12px;border-radius:8px;overflow-wrap:anywhere}.ef-contact-profile-grid small{display:block;color:#9bbce5;margin-bottom:6px}.ef-contact-profile-actions{display:flex;justify-content:flex-end;gap:10px}.ef-contact-profile-view.ef-photo-lightbox{z-index:200050}.ef-photo-lightbox img{max-width:90vw;max-height:85vh;object-fit:contain}`;document.head.append(style);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safePhoto=s=>typeof s==='string'&&/^data:image\/(?:png|jpeg|webp);base64,/i.test(s)?s:'';
function popup(html,klass=''){const el=document.createElement('div');el.className='ef-contact-profile-view '+klass;el.innerHTML=html;document.body.append(el);el.addEventListener('click',e=>{if(e.target===el||e.target.closest('[data-close-contact-popup]'))el.remove()});const onkey=e=>{if(e.key==='Escape'){el.remove();document.removeEventListener('keydown',onkey)}};document.addEventListener('keydown',onkey);return el;}
function photoPopup(photo,name){if(!photo)return;popup(`<div class="ef-contact-profile-box" style="width:auto;max-width:96vw;text-align:center"><div class="ef-contact-profile-head"><h2>${esc(name)} — Photograph</h2><button data-close-contact-popup>Close ✕</button></div><img src="${photo}" alt="${esc(name)}"></div>`,'ef-photo-lightbox')}
function showProfile(contact,member,gang){const c=contact||{},m=member||{};const name=c.name||m.name||'Contact';const photo=safePhoto(c.photo)||safePhoto(m.photo);const fields=[['Full Name',name],['Alias / Street Name',c.alias||m.alias],['Phone Number',c.phone||m.phone],['Gang',c.gang||gang?.title],['Gang Rank / Role',m.rank||m.position||c.rank],['Status',m.status||c.status],['Date of Birth',c.dob],['Last Known Location',c.location],['Physical Description',c.physical],['Vehicles',c.vehicles],['Known Associates',c.associates],['Linked Cases',c.cases],['Intelligence Notes',c.notes||m.notes]];const el=popup(`<div class="ef-contact-profile-box" role="dialog" aria-modal="true" aria-label="Contact profile"><div class="ef-contact-profile-head"><h2>${esc(name)} — Contact Profile</h2><button data-close-contact-popup>Close ✕</button></div>${photo?`<img class="ef-contact-profile-photo" src="${photo}" alt="${esc(name)}" title="Click to enlarge">`:''}<div class="ef-contact-profile-grid">${fields.map(([key,value])=>`<div><small>${esc(key)}</small>${esc(value||'Not recorded')}</div>`).join('')}</div><div class="ef-contact-profile-actions">${c.id?'<button data-edit-from-profile>Edit Contact</button>':''}<button data-close-contact-popup>Close</button></div></div>`);
 el.querySelector('.ef-contact-profile-photo')?.addEventListener('click',()=>photoPopup(photo,name));
 el.querySelector('[data-edit-from-profile]')?.addEventListener('click',()=>{el.remove();window.efContacts?.open(c.id);});
}
// Capture before the directory's delegated click handler and before the old gang handler.
document.addEventListener('click',e=>{
 const view=e.target.closest('[data-contactview]');if(view){e.preventDefault();e.stopImmediatePropagation();const c=window.efContacts?.get()?.find(x=>x.id===view.dataset.contactview);if(c)showProfile(c);return;}
 const edit=e.target.closest('[data-contactedit]');if(edit){e.preventDefault();e.stopImmediatePropagation();window.efContacts?.open(edit.dataset.contactedit);return;}
 const card=e.target.closest('.ef-contact-card');if(card&&e.target.closest('.ef-contact-avatar,.ef-contact-info h3')){const id=card.querySelector('[data-contactedit]')?.dataset.contactedit;const c=window.efContacts?.get()?.find(x=>x.id===id);if(c){e.preventDefault();e.stopImmediatePropagation();showProfile(c);return;}}
 const btn=e.target.closest('[data-gang-contact]');if(!btn)return;
 e.preventDefault();e.stopImmediatePropagation();
 const [gi,mi]=btn.dataset.gangContact.split(':').map(Number);
 const db=typeof database!=='undefined'?database:window.database;const g=db?.gangs?.[gi],m=g?.members?.[mi];if(!m)return;
 const all=window.efContacts?.get()||[];
 const c=all.find(x=>x.id===m.contactId)||all.find(x=>x.name?.trim().toLowerCase()===m.name?.trim().toLowerCase());
 showProfile(c,m,g);
},true);
})();

