/* EFLSPDDB Phase 7B Settings & local investigation recovery. No automatic shared-data overwrites. */
(()=>{'use strict';
const CASES='everfall_lspd_cases_satmap_v1',BIN='eflspddb_deleted_cases_v1',RET='eflspddb_retention_days_v1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const get=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const save=(key,v)=>localStorage.setItem(key,JSON.stringify(v));
const owner=()=>window.EFDBAuth?.user?.role==='owner';
const manager=()=>['owner','director','deputy_director','supervisory_detective','admin'].includes(window.EFDBAuth?.user?.role);
const localCases=()=>get(CASES,[]);
const retention=()=>localStorage.getItem(RET)||'30';
const daysOld=iso=>(Date.now()-new Date(iso).getTime())/86400000;
const root=()=>document.getElementById('extraContent');
function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000)}
function notice(s){const e=document.getElementById('ef7bNotice');if(e)e.textContent=s;}
function open(){if(!window.EFDBAuth?.loggedIn)return; if(typeof showSection==='function')showSection('settings');setTimeout(render,0)}
window.EFDBOpenSettings=open;
function render(){const host=root();if(!host||document.getElementById('extraTitle')?.textContent?.trim().toLowerCase()!=='settings')return;
 const u=window.EFDBAuth?.user||{},bin=get(BIN,[]);
 host.innerHTML=`<div class="ef7b-settings"><p class="ef7b-intro">Detective Bureau control centre · Local browser data is not automatically synchronized with the shared database.</p><div class="ef7b-grid">
 <section class="db-card"><h3>👤 MY PROFILE</h3><p><strong>${esc(u.name||'Detective')}</strong> · ${esc(u.role_title||u.role||'')} · ${esc(u.callsign||'No callsign')}</p><p>Badge: ${esc(u.badge_number||'Not set')}</p><p>For profile changes, use Manage Accounts or your account administrator.</p></section>
 <section class="db-card"><h3>🎨 APPEARANCE</h3><label><input type="checkbox" id="ef7bLight"> Light header</label><p><label><input type="checkbox" id="ef7bCompact"> Compact Settings layout</label></p><p>Map and sidebar widths remain adjustable in the main interface.</p></section>
 <section class="db-card"><h3>💾 BACKUP & RESTORE</h3><p>Export the exact browser storage data used by this installation. Import creates a safety backup first and requires confirmation.</p><button id="ef7bBackup">Export full browser backup</button> <label class="ef7b-import">Restore JSON backup <input id="ef7bRestore" type="file" accept="application/json,.json"></label></section>
 <section class="db-card"><h3>🔒 SECURITY & SESSIONS</h3><p>Login sessions expire after inactivity. You can sign out this device below. Other-device session revocation is not available yet.</p><button id="ef7bLogout">Log out this device</button></section>
 <section class="db-card"><h3>🗂️ INVESTIGATION RETENTION</h3><p>Closed investigations remain in the case list indefinitely. Deleted investigations enter this browser's Recycle Bin.</p><label>Recycle Bin retention <select id="ef7bRetention" ${owner()?'':'disabled'}><option value="7">7 days</option><option value="30">30 days</option><option value="60">60 days</option><option value="90">90 days</option><option value="manual">Until manually deleted</option></select></label><p class="ef7b-hint">Retention is a local policy preference only. No automatic permanent deletion runs in this version.</p></section>
 <section class="db-card"><h3>🩺 DATABASE HEALTH</h3><p>Test your Worker and check the shared cases document.</p><button id="ef7bHealth">Check connection</button><p id="ef7bHealthResult" role="status">Not checked</p></section>
 <section class="db-card"><h3>📜 ACTIVITY & AUDIT</h3><p>Local deletion and restoration history is recorded on this browser. Account-management audit history is stored separately by the authentication service.</p><button id="ef7bAudit">Download local audit log</button></section>
 <section class="db-card"><h3>ℹ️ ABOUT EFLSPDDB</h3><p>Phase 7B · Settings & local recovery preview</p><p>Cloudflare Pages + authenticated Worker + Supabase shared-document foundation.</p><p>Automatic live synchronization, centralized deletion and server-enforced retention are not enabled.</p></section></div>
 <section class="db-card"><h3>🗑️ RECYCLE BIN <small>(${bin.length} records)</small></h3><p>Records deleted on this browser can be restored here. Closed cases are not deleted.</p><div id="ef7bBin">${bin.length?bin.map((r,i)=>`<div class="ef7b-binrow"><span><strong>${esc(r.case?.caseNo||r.case?.id||'Case')}</strong> · Deleted ${esc(new Date(r.deletedAt).toLocaleString())} · ${esc(Math.floor(daysOld(r.deletedAt)))} days ago</span> ${manager()?`<button data-restore="${i}">Restore</button>`:''} ${owner()?`<button data-purge="${i}">Permanently delete</button>`:''}</div>`).join(''):'<p>No locally deleted investigations.</p>'}</div></section>
 <section class="db-card"><h3>🌐 SHARED DATABASE SETUP</h3><div id="ef7bShared"></div></section><p id="ef7bNotice" role="status"></p></div>`;
 const header=document.querySelector('.ef-new-header');const light=host.querySelector('#ef7bLight');light.checked=localStorage.getItem('ef7b_light')==='true';light.onchange=()=>{localStorage.setItem('ef7b_light',String(light.checked));header?.classList.toggle('ef-header-light',light.checked)};
 const compact=host.querySelector('#ef7bCompact');compact.checked=localStorage.getItem('ef7b_compact')==='true';host.querySelector('.ef7b-settings').classList.toggle('ef7b-compact',compact.checked);compact.onchange=()=>{localStorage.setItem('ef7b_compact',String(compact.checked));host.querySelector('.ef7b-settings').classList.toggle('ef7b-compact',compact.checked)};
 const r=host.querySelector('#ef7bRetention');r.value=retention();r.onchange=()=>{localStorage.setItem(RET,r.value);notice('Local retention preference saved. No automatic purge is enabled.')};
 host.querySelector('#ef7bBackup').onclick=()=>download('EFLSPDDB-full-browser-backup-'+new Date().toISOString().slice(0,10)+'.json',{format:'eflspddb-local-backup-v1',createdAt:new Date().toISOString(),storage:Object.fromEntries(Object.keys(localStorage).filter(k=>k.startsWith('ef')||k.startsWith('everfall')).map(k=>[k,localStorage.getItem(k)]))});
 host.querySelector('#ef7bRestore').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{const obj=JSON.parse(await f.text());if(obj.format!=='eflspddb-local-backup-v1'||!obj.storage||typeof obj.storage!=='object'||Array.isArray(obj.storage))throw Error('Not an EFLSPDDB full-browser backup');const keys=Object.keys(obj.storage);if(keys.length>200||keys.some(k=>!(k.startsWith('ef')||k.startsWith('everfall'))||typeof obj.storage[k]!=='string'))throw Error('Invalid backup keys');if(!confirm('Restore '+keys.length+' saved entries to THIS browser? A safety backup will be downloaded first. Reload is required.'))return;download('EFLSPDDB-before-restore.json',{format:'eflspddb-local-backup-v1',createdAt:new Date().toISOString(),storage:Object.fromEntries(Object.keys(localStorage).filter(k=>k.startsWith('ef')||k.startsWith('everfall')).map(k=>[k,localStorage.getItem(k)]))});for(const k of keys)localStorage.setItem(k,obj.storage[k]);alert('Restore complete. Reloading.');location.reload()}catch(err){notice('Restore failed: '+err.message)}};
 host.querySelector('#ef7bLogout').onclick=()=>window.EFDBAuth?.logout();
 host.querySelector('#ef7bHealth').onclick=async()=>{const e=host.querySelector('#ef7bHealthResult');e.textContent='Checking...';try{const response=await fetch('https://eflspddb-auth.danielmcmahon1995.workers.dev/health');if(!response.ok)throw Error('Worker HTTP '+response.status);const health=await response.json();const shared=await window.EFDBAuth.request('/shared-document',{key:'cases',action:'read'});e.textContent='Worker: '+(health.ok?'online':'unexpected response')+' · Shared cases: '+(shared.document?'revision '+shared.document.revision:'not published yet')}catch(err){e.textContent='Connection check failed: '+err.message}};
 host.querySelector('#ef7bAudit').onclick=()=>download('EFLSPDDB-local-audit.json',get('eflspddb_local_case_audit_v1',[]));
 host.querySelector('#ef7bBin').onclick=e=>{const b=e.target.closest('button');if(!b)return;const idx=Number(b.dataset.restore??b.dataset.purge);const rows=get(BIN,[]);const rec=rows[idx];if(!rec)return;if(b.hasAttribute('data-restore')){if(!manager())return;const active=localCases();if(active.some(c=>c.id===rec.case.id)){notice('Case ID already exists; cannot restore.');return}active.push(rec.case);save(CASES,active);rows.splice(idx,1);save(BIN,rows);audit('restore',rec.case);notice('Case restored. Refresh the map to view it.');render()}else if(b.hasAttribute('data-purge')){if(!owner())return;if(!confirm('PERMANENTLY delete '+(rec.case.caseNo||rec.case.id)+' from this browser Recycle Bin? This cannot be undone.'))return;rows.splice(idx,1);save(BIN,rows);audit('permanent_delete',rec.case);render()}};
 // Existing Phase 7A panel is mounted by phase7-shared.js on its next render event.
 setTimeout(()=>{document.dispatchEvent(new MouseEvent('click',{bubbles:true}));const panel=document.getElementById('efSharedPanel');if(panel)host.querySelector('#ef7bShared')?.append(panel)},10);
}
function audit(action,c){const log=get('eflspddb_local_case_audit_v1',[]);log.push({action,caseId:c.id,caseNo:c.caseNo,at:new Date().toISOString(),actor:window.EFDBAuth?.user?.name||'Unknown'});save('eflspddb_local_case_audit_v1',log.slice(-5000))}
window.EFDBRecycleCase=function(c){if(!c||!c.id)return false;const bin=get(BIN,[]);if(!bin.some(r=>r.case?.id===c.id))bin.push({case:c,deletedAt:new Date().toISOString()});try{save(BIN,bin);audit('soft_delete',c);return true}catch{return false}};
// Settings section is rendered by app.js, so enhance only after it has been opened.
document.addEventListener('click',e=>{if(e.target.closest('[data-section="settings"]'))setTimeout(render,20)});
window.addEventListener('efdb-auth-login',()=>{document.querySelector('.ef-new-header')?.classList.toggle('ef-header-light',localStorage.getItem('ef7b_light')==='true')});
})();
;

