/* ===== SOURCE: phase8c-pilot.js ===== */
(()=>{'use strict';
const DATASET='cases',ID='ef8b-sync-test',INTERVAL=2000;let version=null,refreshBusy=false,saveBusy=false,pending=false,dirty=false,debounce=null,connected=false;
const by=id=>document.getElementById(id);
async function api(action,other={}){if(!window.EFDBAuth?.request)throw Error('Log in first');return window.EFDBAuth.request('/live-records',{dataset:DATASET,action,...other})}
function status(t,bad=false){const e=by('ef8b-status');if(e){e.textContent=t;e.style.color=bad?'#ffaaa9':'#a9d7a6'}}
async function load(){if(refreshBusy||saveBusy||!by('ef8b-pilot'))return;refreshBusy=true;try{const r=await api('list');const rec=(r.records||[]).find(x=>x.record_id===ID);version=rec?.version??null;const val=rec?.body?.message??'';const remote=by('ef8b-remote');if(remote)remote.textContent=rec?`Revision ${version} · ${val}`:'No test record exists yet';if(!dirty){const input=by('ef8b-message');if(input&&document.activeElement!==input)input.value=val;}connected=true;status('Live sync connected · checks every 2 seconds');}catch(e){connected=false;status('Connection error: '+e.message,true)}finally{refreshBusy=false}}
async function save(){const input=by('ef8b-message');if(!input||saveBusy)return;const message=input.value.trim();if(!message){status('Enter a test message first.',true);return}if(message.length>300){status('Maximum 300 characters.',true);return}saveBusy=true;try{const r=await api('list');const current=(r.records||[]).find(x=>x.record_id===ID);const body={kind:'sync-test',message,modified_at:new Date().toISOString()};const result=current?await api('update',{id:ID,version:current.version,body}):await api('create',{id:ID,body});version=result.record.version;dirty=false;status('Auto-saved · revision '+version);await load()}catch(e){status('Save failed: '+e.message+' · Your text is still in this browser.',true)}finally{saveBusy=false;if(pending){pending=false;save()}}}
function queueSave(){dirty=true;status('Saving changes shortly…');clearTimeout(debounce);debounce=setTimeout(()=>{if(saveBusy){pending=true;return}save()},800)}
function mount(){const parent=by('ef7bShared');if(!parent||by('ef8b-pilot'))return;const box=document.createElement('section');box.id='ef8b-pilot';box.className='db-card';box.style.cssText='border:1px solid #31562e;padding:16px;border-radius:10px;margin-top:16px;background:#081020;color:#afafaf';box.innerHTML=`<h3 style="color:#dce6e2">PHASE 8C · ALWAYS-ON SYNC PILOT</h3><p>Shared test message only. Real cases and pins are not synchronized yet.</p><label for="ef8b-message">Test message (auto-saves after typing stops)</label><input id="ef8b-message" maxlength="300" placeholder="Test from 1A-3" style="display:block;width:100%;box-sizing:border-box;margin:8px 0 12px;padding:10px;background:#121e31;color:#fff;border:1px solid #afafaf;border-radius:6px"/><div style="display:flex;gap:8px;flex-wrap:wrap"><button id="ef8b-save" type="button" style="background:#31562e;color:#fff">Save now</button><button id="ef8b-refresh" type="button">Check now</button></div><p><strong>Shared value:</strong> <span id="ef8b-remote">Connecting…</span></p><p id="ef8b-status" role="status">Connecting…</p><small>Automatic checks every 2 seconds while this tab is visible. No full-page refresh. Real case and pin storage is unchanged.</small>`;parent.append(box);by('ef8b-message').addEventListener('input',queueSave);by('ef8b-save').onclick=()=>{clearTimeout(debounce);save()};by('ef8b-refresh').onclick=()=>load();load()}
new MutationObserver(mount).observe(document.body,{childList:true,subtree:true});mount();setInterval(()=>{if(document.visibilityState==='visible'&&by('ef8b-pilot')&&!dirty&&!saveBusy)load()},INTERVAL);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')load()});
})();
;

