/* ===== SOURCE: phase8d-pilot.js ===== */
/* Phase 8D opt-in case/pin sharing pilot. No automatic migration or destructive merge. */
(()=>{'use strict';
const DATASET='cases',TEST='ef8b-sync-test';let remote=[],busy=false;
const el=id=>document.getElementById(id);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api=(action,extra={})=>window.EFDBAuth.request('/live-records',{dataset:DATASET,action,...extra});
function status(s,bad=false){const e=el('ef8d-status');if(e){e.textContent=s;e.style.color=bad?'#ffb5b5':'#9bdbb6'}}
function local(){try{return JSON.parse(localStorage.getItem('everfall_lspd_cases_satmap_v1')||'[]')}catch{return []}}
function valid(r){return r&&typeof r==='object'&&!Array.isArray(r)&&typeof r.id==='string'&&r.id.length<101&&/^[a-zA-Z0-9_-]+$/.test(r.id)}
async function refresh(){if(busy||!el('ef8d-pilot'))return;busy=true;try{const result=await api('list');remote=(result.records||[]).filter(x=>x.record_id!==TEST&&x.body?.kind!=='sync-test');const sel=el('ef8d-remote');sel.innerHTML='<option value="">Choose a shared record…</option>'+remote.map(x=>`<option value="${escape(x.record_id)}">${escape(x.body?.caseNo||x.record_id)} · rev ${Number(x.version)||1}</option>`).join('');status(`${remote.length} shared record(s) available. Local records unchanged.`)}catch(e){status('Unable to check shared records: '+e.message,true)}finally{busy=false}}
async function publish(){const id=el('ef8d-local').value,record=local().find(x=>x.id===id);if(!valid(record))return status('Choose a valid local case or pin.',true);if(JSON.stringify(record).length>240000)return status('Record too large to share (embedded image?).',true);if(!confirm(`Share ${record.caseNo||record.id} with authorized detectives? This does not remove the local copy.`))return;busy=true;try{const result=await api('list'),existing=(result.records||[]).find(x=>x.record_id===id);if(existing){status('Already shared. This pilot will not overwrite a remote record. Use the next conflict-safe editing phase.',true);return}await api('create',{id,body:record});status('Published successfully. Other detectives can now import this record.');}catch(e){status('Publish failed: '+e.message,true)}finally{busy=false;refresh()}}
async function importOne(){const id=el('ef8d-remote').value,entry=remote.find(x=>x.record_id===id);if(!entry||!valid(entry.body))return status('Select a valid shared record.',true);const items=local();if(items.some(x=>x.id===id))return status('This record already exists locally. Import blocked to protect existing changes.',true);if(!confirm(`Import ${entry.body.caseNo||id} into this browser? Existing local records will be preserved.`))return;items.unshift({...entry.body,id});try{localStorage.setItem('everfall_lspd_cases_satmap_v1',JSON.stringify(items));status('Imported. Reload the page to display the new pin.');}catch(e){status('Import failed: local browser storage may be full.',true)}}
function mount(){const parent=el('ef7bShared');if(!parent||el('ef8d-pilot'))return;const box=document.createElement('section');box.id='ef8d-pilot';box.className='db-card';box.style.cssText='border:1px solid #47617d;padding:16px;border-radius:10px;margin-top:16px;background:#0b172a;color:#dce6ef';box.innerHTML=`<h3>PHASE 8D · SHARED CASES & PINS — SAFE PILOT</h3><p>This is a controlled publish/import test, <strong>not automatic pin sync yet</strong>. Existing browser data is never replaced.</p><label>Local case or pin to publish</label><select id="ef8d-local" style="display:block;width:100%;margin:8px 0;padding:9px"></select><button id="ef8d-publish" type="button">Publish selected record</button><hr style="border-color:#344b65;margin:15px 0"><label>Shared case or pin to import</label><select id="ef8d-remote" style="display:block;width:100%;margin:8px 0;padding:9px"></select><button id="ef8d-import" type="button">Import selected record</button> <button id="ef8d-check" type="button">Check shared records</button><p id="ef8d-status" role="status">Ready.</p><small>Safeguards: no overwrite, no deletion, no background import. Requires your existing authenticated Worker and investigation permissions. Refreshing the page after import loads the new pin.</small>`;parent.append(box);el('ef8d-local').innerHTML='<option value="">Choose a local record…</option>'+local().filter(valid).map(x=>`<option value="${escape(x.id)}">${escape(x.caseNo||x.id)}</option>`).join('');el('ef8d-publish').onclick=publish;el('ef8d-import').onclick=importOne;el('ef8d-check').onclick=refresh;refresh()}
new MutationObserver(mount).observe(document.body,{childList:true,subtree:true});mount();
})();

;

;
/* ===== SOURCE: phase8e-sync.js ===== */
/* Phase 8E: guarded automatic case/map-pin sharing. Pilot: no remote deletion, no automatic migration. */
(()=>{'use strict';
const KEY='everfall_lspd_cases_satmap_v1',DATASET='cases',TEST='ef8b-sync-test',OPT='ef8e_auto_sync_optin_v1';
const versions=new Map(),pending=new Map(),pendingDeletes=new Map();let busy=false,ready=false,enabled=true,timer=null,lastLocal=new Map(),lastError='',totalSaved=0,totalReceived=0,lastSuccess=null;
const read=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'[]')}catch{return []}};
const eligible=x=>x&&typeof x==='object'&&/^[a-zA-Z0-9_-]{1,100}$/.test(x.id||'')&&x.id!==TEST&&!['EF-26-014','EF-26-011'].includes(x.id);
const hash=x=>JSON.stringify(x);
const api=(action,more={})=>window.EFDBAuth.request('/live-records',{dataset:DATASET,action,...more});
const status=(msg,bad=false)=>{lastError=bad?msg:'';const el=document.getElementById('ef8e-status');if(el){el.textContent=msg;el.style.color=bad?'#ffb3b3':'#a6e4c0'}};
function snapshot(){lastLocal=new Map(read().filter(eligible).map(x=>[x.id,hash(x)]))}
window.EF8E={onLocalSave(records){if(!enabled||!ready)return;const now=new Map(records.filter(eligible).map(x=>[x.id,hash(x)]));for(const x of records.filter(eligible)){if(now.get(x.id)!==lastLocal.get(x.id))pending.set(x.id,structuredClone(x))}for(const id of lastLocal.keys()){if(!now.has(id)){pending.delete(id);if(versions.has(id))pendingDeletes.set(id,versions.get(id));else status('Local-only pin removed (not previously shared).',true)}}lastLocal=now;}};
async function cycle(){if(!enabled||busy||!window.EFDBAuth?.loggedIn||document.visibilityState!=='visible')return;busy=true;try{
const response=await api('list');const remote=(response.records||[]).filter(x=>x.record_id!==TEST&&x.body?.kind!=='sync-test');const local=new Map(read().filter(eligible).map(x=>[x.id,x]));let imported=0,conflicts=0,saved=0;
const remoteIds=new Set(remote.map(x=>x.record_id));
for(const [id,v] of [...versions]){if(!remoteIds.has(id)&&!pendingDeletes.has(id)&&!pending.has(id)){if(window.EF8H3RemovePin?.(id)){versions.delete(id);imported++}}}
const deletedThisCycle=new Set();for(const [id,version] of [...pendingDeletes]){try{await api('delete',{id,version});pendingDeletes.delete(id);versions.delete(id);deletedThisCycle.add(id)}catch(e){if(/409|conflict|missing/i.test(e.message)){pendingDeletes.delete(id);conflicts++}else throw e}}
for(const entry of remote){if(deletedThisCycle.has(entry.record_id)||!eligible(entry.body))continue;const id=entry.record_id;if(entry.body.id!==id)continue;const oldVersion=versions.get(id);if(pending.has(id)){if(oldVersion===undefined||oldVersion!==entry.version){pending.delete(id);conflicts++;continue}continue}
if(!local.has(id)){window.EF8EApplyRemote?.(structuredClone(entry.body));imported++}else if(oldVersion!==undefined&&entry.version!==oldVersion){const current=local.get(id);if(hash(current)===lastLocal.get(id)){window.EF8EApplyRemote?.(structuredClone(entry.body));imported++}else conflicts++}
versions.set(id,entry.version)}
for(const [id,body] of [...pending]){if(JSON.stringify(body).length>240000){pending.delete(id);conflicts++;continue}const existing=remote.find(x=>x.record_id===id);try{if(existing){const known=versions.get(id);if(known===undefined||known!==existing.version){pending.delete(id);conflicts++;continue}const result=await api('update',{id,version:known,body});versions.set(id,result.record.version)}else{const result=await api('create',{id,body});versions.set(id,result.record.version)}pending.delete(id);saved++}catch(e){if(/conflict|already|409/i.test(e.message)){pending.delete(id);conflicts++}else throw e}}
totalSaved+=saved;totalReceived+=imported;lastSuccess=new Date();snapshot();status(conflicts?`Conflict protection: ${conflicts} change(s) not merged. Local data preserved. Review conflicting records before editing.`:`Synced · ${totalSaved} saved · ${totalReceived} received this session · checks every 2 seconds`,conflicts>0);
}catch(e){status('Offline / sync error: '+e.message+'. Local data preserved.',true)}finally{busy=false}}
function mount(){const parent=document.getElementById('ef7bShared');if(!parent||document.getElementById('ef8e-panel'))return;const section=document.createElement('section');section.id='ef8e-panel';section.className='db-card';section.style.cssText='border:1px solid #3c705c;padding:16px;border-radius:10px;margin-top:16px;background:#0b172a;color:#e5f1eb';section.innerHTML='<h3>PHASE 8E · AUTOMATIC PIN SYNC</h3><p>Automatic sharing is always enabled while logged in. New pins and updates are checked every 2 seconds. Existing local pins are NOT bulk-uploaded. Shared pin deletion is enabled for records already synchronised.</p><p id="ef8e-status" role="status">Waiting for login…</p><small>Shared pins sync automatically. Conflict protection preserves local copies for manual review. This uses polling with live notifications when configured.</small>';parent.append(section);status('Connecting when signed in…')}
new MutationObserver(mount).observe(document.body,{childList:true,subtree:true});mount();snapshot();
window.addEventListener('efdb-auth-login',()=>{snapshot();ready=true;if(enabled)cycle()});window.addEventListener('efdb-auth-logout',()=>{ready=false;pending.clear();pendingDeletes.clear();versions.clear();status('Signed out — sync paused')});
timer=setInterval(()=>{if(enabled&&window.EFDBAuth?.loggedIn){ready=true;cycle()}},2000);
// Promptly check for shared updates when returning to the website, while preserving conflict protection.
window.addEventListener('focus',()=>{if(enabled&&window.EFDBAuth?.loggedIn){ready=true;cycle()}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&enabled&&window.EFDBAuth?.loggedIn){ready=true;cycle()}});
window.addEventListener('online',()=>{if(enabled&&window.EFDBAuth?.loggedIn){ready=true;cycle()}});
})();
