/* ===== SOURCE: lspd-cases-gangs-banner-repair.js ===== */
/* Repairs: case empty state and Gangs Delete (window capture precedes old document handlers). */
(()=>{'use strict';
 const body=document.getElementById('recordsBody');
 function fixEmpty(){if(!body)return;body.querySelectorAll('tr').forEach(row=>row.classList.toggle('lspd-empty-case-row',!!row.querySelector('td[colspan="6"]')))}
 if(body){new MutationObserver(fixEmpty).observe(body,{childList:true});fixEmpty()}
 let busy=false;
 function ask(message){return new Promise(resolve=>{
   const layer=document.createElement('div');layer.style.cssText='position:fixed;inset:0;z-index:2147483647;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(0,7,20,.78);backdrop-filter:blur(4px)';
   layer.innerHTML='<section role="alertdialog" aria-modal="true" aria-label="Confirm deletion" style="width:min(440px,100%);background:#162944;border:1px solid #45678d;border-radius:10px;padding:24px;color:#eef6ff;box-shadow:0 20px 65px #0009;font-family:inherit"><h3 style="margin:0 0 12px;font-size:19px">Delete Gang</h3><p id="lspdGangDeleteMessage" style="margin:0 0 24px;color:#c4d6eb;line-height:1.5"></p><div style="display:flex;gap:10px;justify-content:flex-end"><button type="button" data-no style="background:#304968;color:white;border:1px solid #5a7594;border-radius:6px;padding:10px 16px;cursor:pointer">Cancel</button><button type="button" data-yes style="background:#a72d43;color:white;border:1px solid #d04c63;border-radius:6px;padding:10px 16px;cursor:pointer">Delete</button></div></section>';
   layer.querySelector('#lspdGangDeleteMessage').textContent=message;
   const prior=document.activeElement;
   function done(result){document.removeEventListener('keydown',key,true);layer.remove();busy=false;if(prior&&prior.isConnected)prior.focus();resolve(result)}
   function key(e){if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();done(false)}}
   layer.querySelector('[data-no]').onclick=()=>done(false);
   layer.querySelector('[data-yes]').onclick=()=>done(true);
   layer.addEventListener('click',e=>{if(e.target===layer)done(false)});
   document.body.appendChild(layer);document.addEventListener('keydown',key,true);layer.querySelector('[data-no]').focus();
 })}
 window.addEventListener('click',async e=>{
   const btn=e.target.closest?.('button[data-gang-delete],button[data-gangdelete],button[data-dbdelete]');
   if(!btn||busy||!btn.closest('#extraContent')||typeof currentSection==='undefined'||currentSection!=='gangs')return;
   e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();busy=true;
   const i=Number(btn.dataset.gangDelete??btn.dataset.gangdelete??btn.dataset.dbdelete);
   if(!Number.isInteger(i)||i<0||!Array.isArray(database?.gangs)||!database.gangs[i]){busy=false;return}
   const gang=database.gangs[i];
   if(await ask('Delete '+String(gang.title||'this gang')+' and its member roster?')){
     // Resolve by object identity if list changed while confirmation was open.
     const index=database.gangs.indexOf(gang);
     if(index>=0){database.gangs.splice(index,1);saveDb();renderExtra('gangs')}
   }
 },true);
})();

;

;
/* ===== SOURCE: lspd-department-documents.js ===== */
/* LSPD DB Department Documents. Google Docs remain hosted by Google. */
(()=>{'use strict';
const KEY='lspddb_department_documents_v1';
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const docs=()=>{try{const v=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(v)?v:[]}catch{return []}};
const save=v=>localStorage.setItem(KEY,JSON.stringify(v));
const canManage=()=>['owner','admin','high_command','super_admin'].includes(String(window.EFDBAuth?.user?.role||'').toLowerCase());
const validUrl=u=>{try{const p=new URL(u);return p.protocol==='https:'&&['docs.google.com','drive.google.com'].includes(p.hostname)}catch{return false}};
const preview=u=>{try{const p=new URL(u);if(p.hostname==='docs.google.com'){const m=p.pathname.match(/^\/document\/d\/([a-zA-Z0-9_-]+)/);if(m)return 'https://docs.google.com/document/d/'+m[1]+'/preview';const sh=p.pathname.match(/^\/spreadsheets\/d\/([a-zA-Z0-9_-]+)/);if(sh)return 'https://docs.google.com/spreadsheets/d/'+sh[1]+'/preview';const slides=p.pathname.match(/^\/presentation\/d\/([a-zA-Z0-9_-]+)/);if(slides)return 'https://docs.google.com/presentation/d/'+slides[1]+'/preview';}if(p.hostname==='drive.google.com'){const m=p.pathname.match(/^\/file\/d\/([a-zA-Z0-9_-]+)/);if(m)return 'https://drive.google.com/file/d/'+m[1]+'/preview';}return null}catch{return null}};
function render(){
 const title=document.getElementById('extraTitle'),add=document.getElementById('addEntryBtn'),root=document.getElementById('extraContent');if(!root)return;
 title.textContent='DEPARTMENT DOCUMENTS';add.style.display='none';
 const list=docs(),manager=canManage();
 root.innerHTML=`<div class="lspd-docs"><div class="lspd-docs-head"><div><h3>DEPARTMENT DOCUMENTS</h3><p>Read the latest SOPs and reference materials hosted in Google Docs.</p></div>${manager?'<button type="button" class="blue" id="lspdDocsAdd">+ Add Document</button>':''}</div><div class="lspd-docs-list">${list.length?list.map((d,i)=>`<article class="lspd-doc-row"><div class="lspd-doc-info"><i class="fa-solid fa-file-lines"></i><div><strong>${escapeHTML(d.title)}</strong><small>${escapeHTML(d.description||'Google document')}</small></div></div><div class="lspd-doc-actions"><button type="button" data-doc-view="${i}">View</button><a href="${escapeHTML(d.url)}" target="_blank" rel="noopener noreferrer">Open in Google Docs</a>${manager?`<button type="button" data-doc-edit="${i}">Edit</button><button type="button" data-doc-remove="${i}" class="lspd-doc-danger">Remove</button>`:''}</div></article>`).join(''):'<div class="lspd-doc-empty">No documents have been added yet. An authorised administrator can add the Detective Bureau SOP using its Google Docs link.</div>'}</div><div id="lspdDocViewer" class="lspd-doc-viewer" hidden></div><p class="lspd-doc-note">Google controls access to these documents. If a preview is blocked, use Open in Google Docs. Document links saved here are currently stored in this browser; cross-account sharing requires backend support.</p></div>`;
 root.querySelector('#lspdDocsAdd')?.addEventListener('click',()=>editor());
 root.querySelectorAll('[data-doc-view]').forEach(b=>b.addEventListener('click',()=>{const d=docs()[+b.dataset.docView];if(!d)return;const viewer=root.querySelector('#lspdDocViewer'),src=preview(d.url);viewer.hidden=false;viewer.replaceChildren();const h=document.createElement('div');h.className='lspd-doc-viewer-head';const t=document.createElement('strong');t.textContent=d.title;const link=document.createElement('a');link.href=d.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Open in Google Docs';h.append(t,link);viewer.append(h);if(src){const frame=document.createElement('iframe');frame.src=src;frame.title=d.title;frame.referrerPolicy='strict-origin-when-cross-origin';frame.loading='lazy';viewer.append(frame)}else{const note=document.createElement('p');note.textContent='This link cannot be embedded. Open it in Google Docs instead.';viewer.append(note)}viewer.scrollIntoView({block:'nearest',behavior:'smooth'})}));
 if(manager){root.querySelectorAll('[data-doc-edit]').forEach(b=>b.addEventListener('click',()=>editor(+b.dataset.docEdit)));root.querySelectorAll('[data-doc-remove]').forEach(b=>b.addEventListener('click',async()=>{const i=+b.dataset.docRemove,v=docs();if(!v[i])return;const ok=window.LSPDConfirm?await window.LSPDConfirm('Remove Document','Remove this document link from the directory?'):window.confirm('Remove this document link?');if(!ok)return;v.splice(i,1);save(v);render()}))}
}
function editor(index){if(!canManage())return;const v=docs(),old=Number.isInteger(index)?v[index]:null;document.getElementById('lspdDocsDialog')?.remove();const overlay=document.createElement('div');overlay.id='lspdDocsDialog';overlay.className='lspd-doc-overlay';overlay.innerHTML=`<form class="lspd-doc-form"><h3>${old?'Edit':'Add'} Department Document</h3><label>Document title<input name="title" maxlength="100" required placeholder="Detective Bureau SOP"></label><label>Google Docs / Drive link<input name="url" type="url" required placeholder="https://docs.google.com/document/d/..."></label><label>Description (optional)<textarea name="description" rows="3" maxlength="350"></textarea></label><p class="lspd-doc-error" role="alert"></p><div class="lspd-doc-form-actions"><button type="button" data-cancel>Cancel</button><button class="blue" type="submit">Save Document</button></div></form>`;document.body.append(overlay);const form=overlay.querySelector('form');form.elements.title.value=old?.title||'';form.elements.url.value=old?.url||'';form.elements.description.value=old?.description||'';form.querySelector('[data-cancel]').onclick=()=>overlay.remove();overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.remove()});form.onsubmit=e=>{e.preventDefault();const title=form.elements.title.value.trim(),url=form.elements.url.value.trim(),description=form.elements.description.value.trim();if(!validUrl(url)){form.querySelector('.lspd-doc-error').textContent='Use a valid HTTPS Google Docs or Google Drive link.';return}const entry={title,url,description};if(old)v[index]=entry;else v.push(entry);save(v);overlay.remove();render()}}
const prior=window.renderExtra;if(typeof prior==='function'){window.renderExtra=function(section){if(section==='documents'){render();return}return prior.apply(this,arguments)}}
const nav=document.getElementById('lspdDocumentsNav');if(nav){nav.addEventListener('click',()=>{if(typeof window.showSection==='function')window.showSection('documents');else{document.querySelectorAll('#mapView,#recordsView').forEach(e=>e.classList.add('hidden'));document.getElementById('extraView')?.classList.remove('hidden');render()} });}
})();

;

